INSERT INTO `ai_entities` (`id`, `entity_type`, `name`, `name_en`, `slug`, `country`, `origin`, `year`, `nationality`, `field`, `main_theory`, `image_urls`, `summary`, `external_url`, `verification_status`, `created_at`, `updated_at`) VALUES
('entity-th-1', 'theorist', 'ماکسول مک‌کامبز', 'Maxwell McCombs', 'maxwell-mccombs', 'آمریکایی', 'international', 1972, 'آمریکایی', 'برجسته‌سازی و افکار عمومی', 'نظریه تعیین و برجسته‌سازی دستور کار (Agenda-Setting)', ["/images/theorists/maxwell-mccombs.jpg"], 'ماکسول مک‌کامبز (زاده ۱۹۳۸) از نامدارترین استادان علوم ارتباطات در دانشگاه تگزاس در آستین است. او به همراه دونالد شاو در سال ۱۹۷۲ مطالعه تاریخی «چپل هیل» را منتشر ساخت و اثبات نمود رسانه‌ها با برجسته کردن برخی موضوعات، اولویت‌های ذهنی و گفتمانی جامعه را شکل می‌دهند.', NULL, 'verified', NOW(), NOW()),
('entity-th-2', 'theorist', 'دونالد شاو', 'Donald Shaw', 'donald-shaw', 'آمریکایی', 'international', 1972, 'آمریکایی', 'ارتباطات سیاسی و روزنامه‌نگاری', 'تحلیل هم‌بستگی دستور کار رسانه و افکار عمومی', ["/images/theorists/donald-shaw.jpg"], 'دونالد لوئیس شاو استاد برجسته و بازنشسته دانشکده رسانه و روزنامه‌نگاری هاسمن در دانشگاه کارولینای شمالی در چپل هیل است. او هم‌بنیان‌گذار نظریه تعیین اولویت رسانه‌ها و از پیشگامان تاریخ‌نگاری تحلیل محتوا در مطبوعات است.', NULL, 'verified', NOW(), NOW()),
('entity-th-3', 'theorist', 'مارشال مک‌لوهان', 'Marshall McLuhan', 'marshall-mcluhan', 'کانادایی', 'international', 1964, 'کانادایی', 'بوم‌شناسی رسانه و فلسفه ارتباطات', 'رسانه همان پیام است / دهکده جهانی', ["/images/theorists/marshall-mcluhan.jpg"], 'هربرت مارشال مک‌لوهان (۱۹۱۱–۱۹۸۰) فیلسوف، منتقد ادبی و نظریه‌پرداز برجسته کانادایی است که از او به عنوان پیشگوی عصر دیجیتال یاد می‌شود. او مفهوم «دهکده جهانی» را دهه‌ها پیش از پیدایش اینترنت خلق نمود و تحول فناوری را امتداد حواس بشری دانست.', NULL, 'verified', NOW(), NOW()),
('entity-th-4', 'theorist', 'یورگن هابرماس', 'Jürgen Habermas', 'jurgen-habermas', 'آلمانی', 'international', 1962, 'آلمانی', 'نظریه انتقادی و فلسفه سیاسی', 'حوزه عمومی و کنش ارتباطی (Public Sphere)', ["/images/theorists/jurgen-habermas.jpg"], 'یورگن هابرماس (زاده ۱۹۲۹) فیلسوف و جامعه‌شناس پرآوازه آلمانی و چهره شاخص نسل دوم مکتب فرانکفورت است. نظریه او درباره زوال و احیای حوزه عمومی و لزوم گفت‌وگوی عقلانی عاری از سلطه، متن بنیادین فلسفه رسانه در جهان معاصر است.', NULL, 'verified', NOW(), NOW()),
('entity-th-5', 'theorist', 'استوارت هال', 'Stuart Hall', 'stuart-hall', 'بریتانیایی / جامائیکایی', 'international', 1973, 'بریتانیایی / جامائیکایی', 'مطالعات فرهنگی و نشانه‌شناسی', 'مدل رمزگذاری / رمزگشایی (Encoding/Decoding)', ["/images/theorists/stuart-hall.jpg"], 'استوارت مک‌فیل هال (۱۹۳۲–۲۰۱۴) جامعه‌شناس فرهنگی و نظریه‌پرداز پیشگام مکتب بیرمنگام بود. او نشان داد که متون رسانه‌ای دارای معنای ثابت نیستند، بلکه مخاطبان بر پایه پایگاه اجتماعی خود می‌توانند آنها را به صورت سلطه‌پذیر، مذاکره‌ای یا تقابلی رمزگشایی کنند.', NULL, 'verified', NOW(), NOW()),
('entity-th-6', 'theorist', 'جورج گربنر', 'George Gerbner', 'george-gerbner', 'آمریکایی / مجارستانی', 'international', 1976, 'آمریکایی / مجارستانی', 'جامعه‌شناسی رسانه و تحلیل کاشت', 'نظریه کاشت و سندرم جهان بی‌رحم (Cultivation Theory)', ["/images/theorists/george-gerbner.jpg"], 'جورج گربنر (۱۹۱۹–۲۰۰۵) دانشمند برجسته علوم ارتباطات و رئیس ۲۵ ساله دانشکده آننبرگ دانشگاه پنسیلوانیا بود. پروژه ماندگار او موسوم به «شاخص‌های فرهنگی» نشان داد مصرف مداوم تصاویر تلویزیونی، جهان‌بینی هراس‌آلود و حس ناامنی مفرط در جامعه می‌کارد.', NULL, 'verified', NOW(), NOW()),
('entity-th-7', 'theorist', 'الیزابت نوئل-نویمان', 'Elisabeth Noelle-Neumann', 'elisabeth-noelle-neumann', 'آلمانی', 'international', 1974, 'آلمانی', 'روان‌شناسی اجتماعی و افکار عمومی', 'نظریه مارپیچ سکوت (Spiral of Silence)', ["/images/theorists/elisabeth-noelle-neumann.jpg"], 'الیزابت نوئل-نویمان (۱۹۱۶–۲۰۱۰) جامعه‌شناس و دانشمند علوم سیاسی آلمانی بود که سازوکار نظرسنجی مدرن در آلمان را با تأسیس مؤسسه آلنزباخ پایه‌ریزی کرد. نظریه مارپیچ سکوت او توضیح می‌دهد که چگونه ترس از انزوای اجتماعی افراد را وادار به پنهان‌سازی عقاید اقلیت می‌کند.', NULL, 'verified', NOW(), NOW()),
('entity-th-8', 'theorist', 'اروینگ گافمن', 'Erving Goffman', 'erving-goffman', 'کانادایی / آمریکایی', 'international', 1974, 'کانادایی / آمریکایی', 'جامعه‌شناسی خرد و تعامل‌گرایی نمادین', 'تحلیل چارچوب‌بندی و بازنمایی خود در زندگی روزمره', ["/images/theorists/erving-goffman.jpg"], 'اروینگ گافمن (۱۹۲۲–۱۹۸۲) به عنوان تأثیرگذارترین جامعه‌شناس آمریکایی قرن بیستم در حوزه خرد شناخته می‌شود. کتاب «تحلیل چارچوب» او در سال ۱۹۷۴ الگویی جامع برای درک ساختاربندی ذهنی و بسته بندی خبر توسط رسانه‌ها ارائه داد.', NULL, 'verified', NOW(), NOW()),
('entity-th-9', 'theorist', 'پل لازارسفلد', 'Paul Lazarsfeld', 'paul-lazarsfeld', 'اتریشی / آمریکایی', 'international', 1944, 'اتریشی / آمریکایی', 'جامعه‌شناسی تجربی و روش‌شناسی ارتباطات', 'جریان دو مرحله‌ای ارتباط و رهبران افکار (Two-Step Flow)', ["/images/theorists/paul-lazarsfeld.jpg"], 'پل فلیکس لازارسفلد (۱۹۰۱–۱۹۷۶) از ستون‌های اصلی پایه‌گذاری پژوهش‌های نوین ارتباطی در ایالات متحده است. مطالعات ماندگار او در پروژه شهرستان اری نشان داد رسانه‌ها مستقیماً رفتار رأی‌دهندگان را کنترل نمی‌کنند، بلکه نفوذ از کانال رهبران فکری محلی عبور می‌کند.', NULL, 'verified', NOW(), NOW()),
('entity-th-10', 'theorist', 'هارولد لاسول', 'Harold Lasswell', 'harold-lasswell', 'آمریکایی', 'international', 1948, 'آمریکایی', 'علوم سیاسی و تحلیل پروپاگاندا', 'مدل ارتباطی لاسول و کارکردهای سه‌گانه رسانه', ["/images/theorists/harold-lasswell.jpg"], 'هارولد دوایت لاسول (۱۹۰۲–۱۹۷۸) نظریه‌پرداز پیشگام ارتباطات و علوم سیاسی است. مدل خطی مشهور او («چه کسی می‌گوید، چه می‌گوید، در چه کانالی، به چه کسی، و با چه اثری») استاندارد پایه‌ای تحلیل محتوا و فرآیند پیام در تاریخ علم ارتباطات است.', NULL, 'verified', NOW(), NOW()),
('entity-th-11', 'theorist', 'مانوئل کاستلز', 'Manuel Castells', 'manuel-castells', 'اسپانیایی', 'international', 1996, 'اسپانیایی', 'جامعه‌شناسی اینترنت و عصر اطلاعات', 'جامعه شبکه‌ای و قدرت ارتباطات (Network Society)', ["/images/theorists/manuel-castells.jpg"], 'مانوئل کاستلز اولیوان (زاده ۱۹۴۲) از پیشگامان نظریه‌پردازی درباره انقلاب فناوری اطلاعات است. سه‌گانه ماندگار او تحت عنوان «عصر اطلاعات» تغییر بنیادین در ساختار اقتصاد، فرهنگ و جنبش‌های اجتماعی از طریق شبکه‌های ارتباطی را تبیین نمود.', NULL, 'verified', NOW(), NOW()),
('entity-th-12', 'theorist', 'رابرت انتمن', 'Robert Entman', 'robert-entman', 'آمریکایی', 'international', 1993, 'آمریکایی', 'ارتباطات سیاسی و تحلیل اخبار', 'مکانیسم چهارگانه چارچوب‌بندی (Framing Paradigm)', ["/images/theorists/robert-entman.svg"], 'رابرت ام. انتمن استاد بازنشسته رسانه و امور بین‌الملل در دانشگاه جرج واشنگتن است. مقاله جاودانه او در سال ۱۹۹۳ تحت عنوان «چارچوب‌بندی: به سوی شفاف‌سازی یک پارادایم شکسته» دقیق‌ترین تعریف کاربردی از انتخاب و برجسته‌سازی در پیام‌های رسانه‌ای را بنیان نهاد.', NULL, 'verified', NOW(), NOW()),
('entity-th-13', 'theorist', 'شانتو آینگار', 'Shanto Iyengar', 'shanto-iyengar', 'آمریکایی', 'international', 1987, 'آمریکایی', 'روان‌شناسی سیاسی و اثرات رسانه', 'پرایمینگ رسانه‌ای و چارچوب‌های اپیزودیک در برابر موضوعی', ["/images/theorists/shanto-iyengar.svg"], 'شانتو آینگار استاد علوم سیاسی و ارتباطات در دانشگاه استنفورد است. پژوهش‌های آزمایشی او با همکاری دونالد کیندر نشان داد که اخبار تلویزیونی چگونه با تغییر زمینه‌های ذهنی (Priming)، قضاوت‌های سیاسی شهروندان را دستخوش دگرگونی می‌سازند.', NULL, 'verified', NOW(), NOW()),
('entity-th-14', 'theorist', 'دنیس مک‌کوایل', 'Denis McQuail', 'denis-mcquail', 'بریتانیایی', 'international', 1983, 'بریتانیایی', 'نظریه‌پردازی ارتباطات جمعی', 'طبقه‌بندی نظریه‌های ارتباط جمعی و هنجارهای رسانه‌ای', ["/images/theorists/denis-mcquail.svg"], 'دنیس مک‌کوایل (۱۹۳۵–۲۰۱۷) برجسته‌ترین مؤلف متون آموزشی و تحلیلی ارتباطات جمعی در سطح بین‌المللی است. اثر جامع او با عنوان «درآمدی بر نظریه ارتباطات جمعی» دهه‌هاست که به عنوان متن درسی استاندارد در دانشگاه‌های سراسر دنیا تدریس می‌شود.', NULL, 'verified', NOW(), NOW()),
('entity-th-15', 'theorist', 'والتر لیپمن', 'Walter Lippmann', 'walter-lippmann', 'آمریکایی', 'international', 1922, 'آمریکایی', 'روزنامه‌نگاری تحلیلی و فلسفه رسانه', 'تصاویر درون ذهن ما و شبه‌محیط رسانه‌ای (Pseudo-Environment)', ["/images/theorists/walter-lippmann.jpg"], 'والتر لیپمن (۱۸۸۹–۱۹۷۴) روزنامه‌نگار نام‌آور، برنده دو جایزه پولیتزر و فیلسوف سیاسی آمریکایی بود. کتاب تاریخی او «افکار عمومی» (۱۹۲۲) خاستگاه شناخت جهان نمادین و پیش‌درآمد نظریه برجسته‌سازی در علوم ارتباطات به حساب می‌آید.', NULL, 'verified', NOW(), NOW()),
('entity-th-16', 'theorist', 'کرت لوین', 'Kurt Lewin', 'kurt-lewin', 'آلمانی / آمریکایی', 'international', 1947, 'آلمانی / آمریکایی', 'روان‌شناسی اجتماعی و پویایی گروه', 'نظریه دروازه‌بانی (Gatekeeping Theory)', ["/images/theorists/kurt-lewin.svg"], 'کرت لوین (۱۸۹۰–۱۹۴۷) پدر روان‌شناسی اجتماعی نوین و بنیان‌گذار نظریه میدان و پویایی گروهی است. مفهوم «دروازه‌بانان» که او نخستین بار در مورد کانال‌های تغذیه مطرح ساخت، توسط پژوهشگران ارتباطات برای تحلیل گزینش اخبار در رسانه‌ها اقتباس گردید.', NULL, 'verified', NOW(), NOW()),
('entity-th-17', 'theorist', 'پیر بوردیو', 'Pierre Bourdieu', 'pierre-bourdieu', 'فرانسوی', 'international', 1996, 'فرانسوی', 'جامعه‌شناسی فرهنگ و میدان قدرت', 'میدان ژورنالیسم، سرمایه نمادین و خشونت نمادین', ["/images/theorists/pierre-bourdieu.jpg"], 'پیر بوردیو (۱۹۳۰–۲۰۰۲) از نافذترین جامعه‌شناسان نیمه دوم قرن بیستم و استاد کولژ دو فرانس بود. اثر انتقادی او «درباره تلویزیون» وابستگی فزاینده حوزه رسانه به منطق بازار و پیامدهای فاجعه‌بار آن برای اندیشه و دموکراسی را کالبدشکافی کرد.', NULL, 'verified', NOW(), NOW()),
('entity-th-18', 'theorist', 'ژان بودریار', 'Jean Baudrillard', 'jean-baudrillard', 'فرانسوی', 'international', 1981, 'فرانسوی', 'فلسفه پساساختارگرا و نقد رسانه', 'وانموده و بیش‌واقعیت رسانه‌ای (Simulacra and Simulation)', ["/images/theorists/jean-baudrillard.jpg"], 'ژان بودریار (۱۹۲۹–۲۰۰۷) فیلسوف و نظریه‌پرداز فرهنگی فرانسوی است که با طرح مفاهیمی چون «وانموده» و «بیش‌واقعیت»، نشان داد چگونه بازنمایی‌های رسانه‌ای در عصر مدرن جایگزین واقعیت اصیل شده و مرز میان حقیقت و سراب را محو نموده‌اند.', NULL, 'verified', NOW(), NOW()),
('entity-th-19', 'theorist', 'تئودور آدورنو', 'Theodor Adorno', 'theodor-adorno', 'آلمانی', 'international', 1947, 'آلمانی', 'نظریه انتقادی و مکتب فرانکفورت', 'صنعت فرهنگ و کالایی‌شدن آگاهی (Culture Industry)', ["/images/theorists/theodor-adorno.jpg"], 'تئودور ویزنگروند آدورنو (۱۹۰۳–۱۹۶۹) فیلسوف، جامعه‌شناس و نظریه‌پرداز فرهنگ مکتب فرانکفورت بود. او همراه هورکهایمر با خلق مفهوم «صنعت فرهنگ»، اثبات نمود که رسانه‌های توده‌ای هنر و فرهنگ را به ابزار انقیاد و استانداردسازی افکار توده‌ها تبدیل کرده‌اند.', NULL, 'verified', NOW(), NOW()),
('entity-th-20', 'theorist', 'ملوین دفلور', 'Melvin DeFleur', 'melvin-defleur', 'آمریکایی', 'international', 1976, 'آمریکایی', 'جامعه‌شناسی ارتباطات جمعی', 'نظریه وابستگی به سیستم رسانه‌ای (Media Dependency)', ["/images/theorists/melvin-defleur.svg"], 'ملوین ال. دفلور (۱۹۲۳–۲۰۱۷) پژوهشگر پرسابقه علوم ارتباطات بود که نظریه وابستگی به سیستم رسانه را به همراه ساندرا بال-روکیچ فرمول‌بندی کرد. بر اساس این نظریه، در زمان بحران‌ها و تلاطم‌های اجتماعی، وابستگی شناختی و رفتاری جامعه به رسانه‌ها به نقطه اوج می‌رسد.', NULL, 'verified', NOW(), NOW()),
('entity-th-21', 'theorist', 'ساندرا بال-روکیچ', 'Sandra Ball-Rokeach', 'sandra-ball-rokeach', 'آمریکایی', 'international', 1976, 'آمریکایی', 'بوم‌شناسی ارتباطی و اثرات رسانه‌ای', 'بوم‌شناسی ارتباطی و سیستم وابستگی به رسانه‌ها', ["/images/theorists/sandra-ball-rokeach.jpg"], 'ساندرا بال-روکیچ استاد برجسته ارتباطات و جامعه‌شناسی در دانشکده آننبرگ دانشگاه کالیفرنیای جنوبی (USC) است. او هم‌بنیان‌گذار نظریه وابستگی و رهبر پروژه بین‌المللی متامورفوز برای تحلیل پیوند رسانه‌ها و محله‌های شهری است.', NULL, 'verified', NOW(), NOW()),
('entity-th-22', 'theorist', 'هنری جنکینز', 'Henry Jenkins', 'henry-jenkins', 'آمریکایی', 'international', 2006, 'آمریکایی', 'رسانه‌های دیجیتال و همگرایی', 'فرهنگ همگرایی و رسانه مشارکتی (Convergence Culture)', ["/images/theorists/henry-jenkins.jpg"], 'هنری جنکینز (زاده ۱۹۵۸) استاد کرسی ارتباطات، روزنامه‌نگاری و هنرهای سینمایی دانشگاه کالیفرنیای جنوبی است. او مدیر سابق برنامه مطالعات تطبیقی رسانه در MIT بود و نظریه همگرایی رسانه‌ای و فرهنگ مشارکت هواداران را تبیین کرد.', NULL, 'verified', NOW(), NOW()),
('entity-th-23', 'theorist', 'استیگ هیارورد', 'Stig Hjarvard', 'stig-hjarvard', 'دانمارکی', 'international', 2008, 'دانمارکی', 'جامعه‌شناسی رسانه‌ای‌شدن', 'رسانه‌ای‌شدن فرهنگ و جامعه (Mediatization of Culture)', ["/images/theorists/stig-hjarvard.svg"], 'استیگ هیارورد استاد مطالعات فیلم و رسانه در دانشگاه کپنهاگ دانمارک است. اثر دوران‌ساز او مفهوم «رسانه‌ای‌شدن» را به عنوان یک فرآیند کلان مدرنیته هم‌ردیف با جهانی‌شدن و شهرنشینی در کانون تحلیل علوم ارتباطات قرار داد.', NULL, 'verified', NOW(), NOW()),
('entity-th-24', 'theorist', 'نیک کولدری', 'Nick Couldry', 'nick-couldry', 'بریتانیایی', 'international', 2003, 'بریتانیایی', 'جامعه‌شناسی رسانه و اخلاق ارتباطات', 'مناسک رسانه و استعمارگری داده‌ها (Data Colonialism)', ["/images/theorists/nick-couldry.svg"], 'نیک کولدری استاد جامعه‌شناسی و نظریه رسانه در مدرسه اقتصاد و علوم سیاسی لندن (LSE) است. او نقدهای پیشتازی درباره تمرکز قدرت نمادین در رسانه‌ها و استعمار جدید داده‌ها توسط پلتفرم‌های غول‌پیکر ارائه کرده است.', NULL, 'verified', NOW(), NOW()),
('entity-th-25', 'theorist', 'دانیل کانمن', 'Daniel Kahneman', 'daniel-kahneman', 'آمریکایی / اسرائیلی', 'international', 1981, 'آمریکایی / اسرائیلی', 'علوم شناختی و سوگیری‌های رسانه‌ای', 'نظریه چشم‌انداز و اثر چارچوب‌بندی بر قضاوت (Prospect Theory)', ["/images/theorists/daniel-kahneman.jpg"], 'دانیل کانمن (۱۹۳۴–۲۰۲۴) برنده جایزه نوبل اقتصاد و استاد دانشگاه پرینستون بود. آزمایش‌های تجربی او به همراه عاموس تورسکی نشان داد که مغز انسان چگونه تحت تأثیر نحوه بیان رسانه‌ای (چارچوب سود در برابر زیان)، تصمیمات متضادی اتخاذ می‌کند.', NULL, 'verified', NOW(), NOW()),
('entity-th-26', 'theorist', 'دیوید آلتهاید', 'David Altheide', 'david-altheide', 'آمریکایی', 'international', 1979, 'آمریکایی', 'بوم‌شناسی رسانه و جامعه‌شناسی هراس', 'منطق رسانه (Media Logic) و گفتمان ترس عمومی', ["/images/theorists/david-altheide.svg"], 'دیوید آلتهاید استاد ممتاز بازنشسته در دانشگاه ایالتی آریزونا است. او با معرفی مفهوم «منطق رسانه»، نشان داد که رسانه‌ها دارای قواعد زبانی و نمایشی خاصی هستند که سایر نهادهای جامعه برای بقا ناچار به انطباق با این منطق می‌گردند.', NULL, 'verified', NOW(), NOW()),
('entity-th-27', 'theorist', 'رولان بارت', 'Roland Barthes', 'roland-barthes', 'فرانسوی', 'international', 1957, 'فرانسوی', 'نشانه‌شناسی ساختارگرا و نقد فرهنگ', 'اسطوره‌شناسی رسانه و معانی ضمنی نشانه‌ها', ["/images/theorists/roland-barthes.jpg"], 'رولان بارت (۱۹۱۵–۱۹۸۰) نشانه‌شناس، فیلسوف و منتقد نامدار فرانسوی است. کتاب درخشان او «اسطوره‌ها» نشان داد که چگونه متون رسانه‌ای و تبلیغات بازرگانی، مفاهیم ایدئولوژیک برساخته را به عنوان «امر طبیعی و بدیهی» به خورد جامعه می‌دهند.', NULL, 'verified', NOW(), NOW()),
('entity-th-28', 'theorist', 'ایلیا کتز', 'Elihu Katz', 'elihu-katz', 'آمریکایی / اسرائیلی', 'international', 1974, 'آمریکایی / اسرائیلی', 'جامعه‌شناسی ارتباطات و مطالعات مخاطب', 'رویکرد استفاده و خشنودی (Uses and Gratifications)', ["/images/theorists/elihu-katz.jpg"], 'ایلیا کتز (۱۹۲۶–۲۰۲۱) از پیشگامان تغییر پارادایم در مطالعات مخاطب بود. او به جای بررسی منفعلانه تأثیر رسانه بر مخاطب، پرسش محوری را به این تغییر داد که: «مخاطبان چه استفاده‌هایی از رسانه‌ها می‌کنند و چه نیازهایی را برآورده می‌سازند؟»', NULL, 'verified', NOW(), NOW()),
('entity-th-29', 'theorist', 'فیلیپ تیچنور', 'Phillip Tichenor', 'phillip-tichenor', 'آمریکایی', 'international', 1970, 'آمریکایی', 'ارتباطات جمعی و شکاف آگاهی', 'فرضیه شکاف آگاهی (Knowledge Gap Hypothesis)', ["/images/theorists/phillip-tichenor.jpg"], 'فیلیپ جی. تیچنور استاد روزنامه‌نگاری و جامعه‌شناسی دانشگاه مینه‌سوتا بود. او به همراه همکارانش اثبات کرد که دسترسی بیشتر به جریان اطلاعات در جامعه، شکاف آگاهی میان طبقات فرادست و فرودست را به جای کاهش، تعمیق می‌بخشد.', NULL, 'verified', NOW(), NOW()),
('entity-th-30', 'theorist', 'دیوید منینگ وایت', 'David Manning White', 'david-manning-white', 'آمریکایی', 'international', 1950, 'آمریکایی', 'جامعه‌شناسی خبر و اتاق‌های خبر', 'مطالعه آقای گیتس و فرآیند گزینشگری در دروازه‌بانی', ["/images/theorists/david-manning-white.svg"], 'دیوید منینگ وایت (۱۹۱۷–۱۹۹۳) پژوهشگر پرسابقه روزنامه‌نگاری دانشگاه بوستون بود. مطالعه تجربی او روی یک سردبیر تلکس خبری به نام «آقای گیتس»، نخستین آزمون تجربی بود که سوگیری‌ها و سلایق فردی دروازه‌بان در پذیرش یا رد اخبار را عیان ساخت.', NULL, 'verified', NOW(), NOW()),
('entity-th-31', 'theorist', 'نیل پستمن', 'Neil Postman', 'neil-postman', 'آمریکایی', 'international', 1931, 'آمریکایی', 'بوم‌شناسی رسانه و منتقد فرهنگی', 'بوم‌شناسی رسانه و سرگرم‌شدن تا سرحد مرگ', ["/images/theorists/neil-postman.jpg"], 'نیل پستمن، نظریه‌پرداز برجسته ارتباطات و شاگرد و همکار مارشال مک‌لوهان بود که اصطلاح «بوم‌شناسی رسانه» را رسمیت بخشید و اثرات مخرب تلویزیون بر گفتمان عمومی را بررسی کرد.', NULL, 'verified', NOW(), NOW()),
('entity-th-32', 'theorist', 'دالاس اسمایت', 'Dallas Smythe', 'dallas-smythe', 'کانادایی', 'international', 1907, 'کانادایی', 'اقتصاد سیاسی ارتباطات', 'کالایی‌شدن مخاطب (Audience Commodity)', ["/images/theorists/dallas-smythe.svg"], 'پدر اقتصاد سیاسی ارتباطات که مقاله ماندگار او در سال ۱۹۷۷ با عنوان «نقطه کور مارکسیسم غربی»، توجه پژوهشگران جهان را به فروش زمان مخاطب توسط رسانه‌ها جلب کرد.', NULL, 'verified', NOW(), NOW()),
('entity-th-33', 'theorist', 'یوهان گالتونگ', 'Johan Galtung', 'johan-galtung', 'نروژی', 'international', 1930, 'نروژی', 'جامعه‌شناسی، مطالعات صلح و خبر', 'ارزش‌های خبری (News Values) و ژورنالیسم صلح', ["/images/theorists/johan-galtung.jpg"], 'جامعه‌شناس و ریاضی‌دان نامدار نروژی که مدل ۱۲ عاملی ارزش‌های خبری را همراه با ماری هولمبو روگ صورتبندی کرد و بعدها مکتب ژورنالیسم صلح را بنیان گذاشت.', NULL, 'verified', NOW(), NOW()),
('entity-th-34', 'theorist', 'ریچارد پتی', 'Richard Petty', 'richard-petty', 'آمریکایی', 'international', 1951, 'آمریکایی', 'روان‌شناسی اجتماعی و اقناع', 'مدل احتمال بسط (Elaboration Likelihood Model - ELM)', ["/images/theorists/richard-petty.svg"], 'روان‌شناس شناختی برجسته و استاد دانشگاه ایالتی اوهایو که همراه جان کاسیوپو یکی از پرکاربردترین الگوهای اقناع رسانه‌ای در جهان را صورت‌بندی نمود.', NULL, 'verified', NOW(), NOW()),
('entity-th-35', 'theorist', 'کارل وایک', 'Karl Weick', 'karl-weick', 'آمریکایی', 'international', 1936, 'آمریکایی', 'ارتباطات سازمانی و نظریه سیستم‌ها', 'حس‌سازی سازمانی (Sensemaking in Organizations)', ["/images/theorists/karl-weick.svg"], 'پژوهشگر برجسته رفتارهای سازمانی که مفهوم خلق معنا و حس‌سازی در شرایط بحرانی و پرابهام را وارد دانش مدیریت ارتباطات نمود.', NULL, 'verified', NOW(), NOW()),
('entity-th-36', 'theorist', 'لوسی کونگ', 'Lucy Küng', 'lucy-kung', 'سوئیسی / بریتانیایی', 'international', NULL, 'سوئیسی / بریتانیایی', 'مدیریت و استراتژی رسانه', 'مدیریت استراتژیک در رسانه و رهبری تحول دیجیتال', ["/images/theorists/lucy-kung.svg"], 'از سرشناس‌ترین صاحب‌نظران بین‌المللی در حوزه استراتژی رسانه، دوسوتوانی سازمانی و گذار بنگاه‌های خبری به محیط‌های دیجیتال و هوش مصنوعی.', NULL, 'verified', NOW(), NOW()),
('entity-th-37', 'theorist', 'زیزی پاپاچاریسی', 'Zizi Papacharissi', 'zizi-papacharissi', 'یونانی / آمریکایی', 'international', NULL, 'یونانی / آمریکایی', 'ارتباطات سیاسی و رسانه‌های اجتماعی', 'عمومیت‌های عاطفی (Affective Publics)', ["/images/theorists/zizi-papacharissi.svg"], 'استاد نامدار ارتباطات و علوم سیاسی در دانشگاه ایلینوی شیکاگو و سردبیر ارشد نشریه Social Media + Society، پیشگام پژوهش پیرامون پیوند احساسات و سیاست در شبکه‌های اجتماعی.', NULL, 'verified', NOW(), NOW()),
('entity-th-38', 'theorist', 'دیوید هزموندهالگ', 'David Hesmondhalgh', 'david-hesmondhalgh', 'بریتانیایی', 'international', 1963, 'بریتانیایی', 'صنایع فرهنگی و اقتصاد سیاسی ارتباطات', 'نظریه صنایع فرهنگی (The Cultural Industries)', ["/images/theorists/david-hesmondhalgh.svg"], 'استاد رسانه، موسیقی و فرهنگ در دانشگاه لیدز و نویسنده کتاب مرجع «صنایع فرهنگی» که جامع‌ترین تحلیل انتقادی از مدیریت ریسک در تولیدات نمادین و سرگرمی را ارائه داده است.', NULL, 'verified', NOW(), NOW()),
('entity-th-39', 'theorist', 'دیوید نیبورگ', 'David Nieborg', 'david-nieborg', 'هلندی / کانادایی', 'international', NULL, 'هلندی / کانادایی', 'پلتفرمی‌شدن و مطالعات بازی', 'پلتفرمی‌شدن تولید رسانه (Platformization)', ["/images/theorists/david-nieborg.svg"], 'استاد مطالعات رسانه در دانشگاه تورنتو و یکی از نظریه‌پردازان اصلی مفهوم پلتفرمی‌شدن و کالای مشروط در اقتصاد فرهنگ دیجیتال.', NULL, 'verified', NOW(), NOW());

-- card-1: تعیین و برجسته‌سازی دستور کار
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`) VALUES
('doc-card-1', 'card', 'card-1', 'mc-001', 'تعیین و برجسته‌سازی دستور کار', 'Agenda-Setting Theory', 'theory', 'رسانه‌ها لزوماً به مخاطبان دیکته نمی‌کنند که «چگونه فکر کنند»، اما با موفقیتی چشمگیر تعیین می‌کنند که «درباره چه مسائلی فکر کنند». اولویت‌بندی موضوعات در خروجی رسانه‌ها (Media Agenda) از طریق انتقال برجستگی به اولویت‌های ذهنی و گفتمانی شهروندان (Public Agenda) منتقل می‌شود و دستور کار عمومی جامعه …', 'https://resaname.ir/cards/card-1', 'fa', 'آمریکایی', 'international', 'd06b835fb168eb8299e9380c8e3e7ae02b4dc9e4b0924cfe39165bd7fa484c40', '2026-10-14 15:42:11', NOW());
INSERT INTO `ai_document_sections` (`id`, `document_id`, `section_key`, `section_title`, `content`, `content_hash`, `sort_order`, `created_at`, `updated_at`) VALUES
('sec-card-1-1', 'doc-card-1', 'definition', 'تعریف', 'جامعه‌شناسی ارتباطات / افکار عمومی / اثرات شناختی رسانه

رسانه‌ها لزوماً به مخاطبان دیکته نمی‌کنند که «چگونه فکر کنند»، اما با موفقیتی چشمگیر تعیین می‌کنند که «درباره چه مسائلی فکر کنند».

اولویت‌بندی موضوعات در خروجی رسانه‌ها (Media Agenda) از طریق انتقال برجستگی به اولویت‌های ذهنی و گفتمانی شهروندان (Public Agenda) منتقل می‌شود و دستور کار عمومی جامعه را شکل می‌دهد.', '8eeb44c543987e5043b6ba9a0340445fb9a5e47fab1bd87db91d6e7878ddad5e', 1, NOW(), NOW()),
('sec-card-1-2', 'doc-card-1', 'theoretical_framework', 'چارچوب نظری', '۱. بستر تاریخی و صورت‌بندی اولیه نظریه
نظریه تعیین و برجسته‌سازی دستور کار (Agenda-Setting Theory) یکی از اثرگذارترین، مستندترین و آزمون‌شده‌ترین الگوهای تبیین اثرات رسانه‌های جمعی در تاریخ علوم ارتباطات است. این نظریه نخستین‌بار در سال ۱۹۷۲ توسط ماکسول مک‌کامبز (Maxwell McCombs) و دونالد شاو (Donald Shaw) با انتشار مطالعه مشهور «چپل هیل» (Chapel Hill Study) در نشریه Public Opinion Quarterly معرفی شد.

پژوهشگران در جریان انتخابات ریاست‌جمهوری سال ۱۹۶۸ ایالات متحده، اولویت‌های خبری رسانه‌های محلی و ملی (مطبوعات و تلویزیون) را با اولویت‌های ذهنی رأی‌دهندگان مردد مقایسه کردند و همبستگی خیره‌کننده‌ای (بالای ۰/۹) میان «دستور کار رسانه‌ها» (Media Agenda) و «دستور کار افکار عمومی» (Public Agenda) یافتند.

ریشه‌های فلسفی این نگرش به اثر ماندگار والتر لیپمن (Walter Lippmann) با عنوان Public Opinion در سال ۱۹۲۲ بازمی‌گردد؛ جایی که او میان «جهان واقعی پیرامون» و «شبه‌محیط بازنمایی‌شده توسط رسانه‌ها» تمایز نهاد و نشان داد تصاویر درون ذهن شهروندان محصول تصاویر رسانه‌ای است. سال‌ها بعد، برنارد کوهن (Bernard Cohen) در سال ۱۹۶۳ این بینش را در جمله‌ای جاودانه صورت‌بندی کرد: «رسانه‌ها ممکن است در گفتن این‌که مردم چگونه فکر کنند موفق نباشند، اما در گفتن این‌که به چه چیزی فکر کنند، به‌طرزی شگفت‌انگیز موفق‌اند».

۲. سطوح سه‌گانه برجسته‌سازی (سیر تکامل نظری)
نظریه در طول پنج دهه تکامل مداوم، از یک مدل تک‌سطحی به چارچوبی جامع در سه سطح متمایز ارت', '269a06caaed8f03a4314f03739887b8d221855347f211d624b91aaa97d3777a5', 2, NOW(), NOW()),
('sec-card-1-3', 'doc-card-1', 'components', 'اجزای نظری', '• انتقال برجستگی (Salience Transfer): سازوکار بنیادین انتقال اهمیت از رسانه به ذهن مخاطب.
• سطح اول برجسته‌سازی (Objects / Issues): تعیین اینکه کدام موضوعات و رویدادهای کلی در صدر توجه عمومی قرار گیرند.
• سطح دوم برجسته‌سازی (Attributes / Framing): گزینش و برجسته‌سازی جنبه‌ها، صفات و ویژگی‌های خاص یک موضوع.
• سطح سوم یا برجسته‌سازی شبکه‌ای (Network Agenda-Setting): انتقال بسته‌های هم‌رخداد و پیوندهای تداعی‌گر میان عناصر مختلف به شبکه شناختی مخاطبان.
• نیاز به جهت‌یابی (Need for Orientation - NFO): متغیر تعدیل‌کننده روان‌شناختی مبتنی بر دو شاخص «ارتباط موضوع» (Relevance) و «ابهام ادراک‌شده» (Uncertainty).
• برجستگی ذاتی موضوع (Issue Obtrusiveness): تمایز میان موضوعات ملموس و تجربه‌پذیر روزمره در برابر موضوعات ناملموس و غیرمستقیم.', '93f6b70c326176f26f593cafe4d5e532b56a89791afacb20527f2935ad414242', 3, NOW(), NOW()),
('sec-card-1-4', 'doc-card-1', 'applications', 'کاربردها', 'قا یافته است:

• سطح اول برجسته‌سازی (برجستگی موضوعات / First-Level Agenda-Setting): تمرکز بر این پرسش بنیادین که «رسانه‌ها چه موضوعاتی (Objects) را در کانون توجه قرار می‌دهند؟». در این سطح، تکرار، اندازه تیترها، تقدم مکانی در صفحات و زمان پخش در اخبار تلویزیونی، باعث انتقال برجستگی رویدادها از خروجی‌های خبری به ذهنیت مخاطبان می‌شود.
• سطح دوم برجسته‌سازی (برجستگی ویژگی‌ها / Second-Level Agenda-Setting): بررسی این مسئله که رسانه‌ها علاوه بر اصل موضوع، «چه ویژگی‌ها، صفات و لحن‌هایی (Attributes)» را در خصوص آن موضوع پررنگ می‌سازند. این سطح قرابت عمیقی با مفهوم «چارچوب‌بندی» (Framing) پیدا می‌کند و نحوه ارزیابی و قضاوت عمومی را جهت‌دهی می‌نماید.
• سطح سوم برجسته‌سازی (برجسته‌سازی شبکه‌ای / Network Agenda-Setting - NAS): این مدل پیشرفته که در دهه ۲۰۱۰ توسط لی گوئو (Lei Guo) و مک‌کامبز مطرح شد، ادعا می‌کند رسانه‌ها «شبکه همبستگی و تداعی میان موضوعات و صفات» را در شبکه شناختی ذهن مخاطب بازتولید می‌کنند؛ یعنی مشخص می‌سازند کدام مفاهیم هم‌زمان و در پیوند با یکدیگر اندیشیده شوند (مثلاً پیوند مداوم مهاجرت با ناامنی شغلی).

۳. متغیرهای میانجی و شروط تعدیل‌کننده اثر
تأثیرگذاری دستور کار رسانه امری ماشینی و یک‌نواخت برای همه افراد نیست، بلکه تابع متغیرهای روان‌شناختی و زمینه‌ای معین است:
• نیاز به جهت‌یابی (Need for Orientation - NFO): این متغیر روان‌شناختی با دو شاخص «میزان ارتباط موضوع با زندگی فرد» (Relevance) و «میزان ابهام و بلاتکل', '5a1bd2f8cdb49fe034305497ba430b38202264d2b31dae4cb8fe3c9c7d01001a', 4, NOW(), NOW()),
('sec-card-1-5', 'doc-card-1', 'examples', 'مثال‌ها', 'در انتخابات‌های سیاسی، تسلط یک سوژه (نظیر رسوایی اخلاقی یک کاندیدا یا یک شاخص بحرانی اقتصادی) در بخش ترند شبکه‌های اجتماعی، صفحه اول خبرگزاری‌ها و بخش‌های خبری تلویزیون، توجه کل جامعه را از سایر برنامه‌ها منحرف کرده و همان سوژه را به ملاک اصلی داوری تبدیل می‌کند.

در عصر پلتفرم‌ها همچنین پدیده «برجسته‌سازی معکوس» (Reverse Agenda-Setting) مشاهده می‌شود؛ جایی که هشتگ‌های پرمخاطب کاربران و جریان‌های وایرال اینستاگرامی، خبرگزاری‌های سنتی و مقامات حاکمیتی را ناگزیر به پاسخگویی و تنظیم دستور کار رسمی می‌سازند.', '0b2fcbd0bb9133dc6ad6f5daf35e08ae5baf3567e899a756a6b736b7203e719a', 5, NOW(), NOW()),
('sec-card-1-6', 'doc-card-1', 'criticism', 'نقدها', '۱. مسئله جهت علیت (Causality): اثبات اینکه آیا پوشش رسانه‌ای علت اولویت عمومی است یا رسانه‌ها صرفاً بازتاب‌دهنده واقعیت‌های عینی و دغدغه‌های از پیش موجود مردم‌اند، در پژوهش‌های میدانی پیچیده است.
۲. تکه‌تکه‌شدن مخاطب در عصر دیجیتال: در محیط پرانتخاب وب و کانال‌های شخصی‌سازی‌شده، اثر یکپارچه رسانه‌های سراسری تضعیف شده و خرده‌دستورکارهای متعدد در میان گروه‌های اجتماعی جایگزین دستور کار ملی واحد گردیده است.
۳. سوگیری در تحلیل محتوا: کدگذاری حجم پوشش خبری و سنجش دقیق وزن رسانه‌ای به قضاوت روش‌شناختی پژوهشگران وابسته است.', 'db2a6755943a790c9d6732ec1ace58573a3d36a6edd8ab9bfb740390cc5c1744', 6, NOW(), NOW()),
('sec-card-1-10', 'doc-card-1', 'references', 'منابع', 'استناد علمی مبنا (APA 7): McCombs & Shaw (1972)', 'ff5b5e33341b8606619fb5be49777e455fdb60d9a53782878ac80a275f430e2c', 10, NOW(), NOW());
