-- card-10: اثر شخص سوم
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`) VALUES
('doc-card-10', 'card', 'card-10', 'mc-010', 'اثر شخص سوم', 'Third-Person Effect', 'effect', 'افراد تمایل دارند اثر پیام‌های رسانه‌ای (به‌ویژه پیام‌های منفی و اقناعی) را بر «دیگران» بیش از اثر آن بر «خودشان» برآورد کنند (مؤلفه ادراکی). این ادراک نابرابر می‌تواند به کنش‌هایی مانند حمایت از سانسور یا مقررات‌گذاری منجر شود (مؤلفه رفتاری).', 'https://resaname.ir/cards/card-10', 'fa', NULL, NULL, '8eaf460420615748ce13cecb06126317cbc62a5a11e94b5cdf603ca059b79653', '2026-10-14 01:43:01', NOW());
INSERT INTO `ai_document_sections` (`id`, `document_id`, `section_key`, `section_title`, `content`, `content_hash`, `sort_order`, `created_at`, `updated_at`) VALUES
('sec-card-10-1', 'doc-card-10', 'definition', 'تعریف', 'روان‌شناسی اجتماعی / ادراک اثرات رسانه

افراد تمایل دارند اثر پیام‌های رسانه‌ای (به‌ویژه پیام‌های منفی و اقناعی) را بر «دیگران» بیش از اثر آن بر «خودشان» برآورد کنند (مؤلفه ادراکی). این ادراک نابرابر می‌تواند به کنش‌هایی مانند حمایت از سانسور یا مقررات‌گذاری منجر شود (مؤلفه رفتاری).', 'a2d8e335c5af239adee8a80931b372111d7f8ff25b213331f176d74604fa690e', 1, NOW(), NOW()),
('sec-card-10-2', 'doc-card-10', 'theoretical_framework', 'چارچوب نظری', '۱. بنیان و منطق نظری
ادعای محوری اثر شخص سوم این است که مواجهه با پیام‌های رسانه‌ای می‌تواند ازطریق سازوکارهای روان‌شناختی و شناختی مشخص، باورها، نگرش‌ها و رفتارهای مخاطب را دگرگون کند. دبلیو. فیلیپس دیویسون (۱۹۸۳) کوشید دقیقاً مشخص کند کدام سازوکارها در عمل هستند و تحت چه شرایطی اثر رخ می‌دهد. در این سنت، اثر رسانه جادو نیست؛ فرایندی منظم است که شرایط مرزی آن — پیام، منبع، کانال و مخاطب — قابل شناسایی و آزمون است.

بر اساس اثر شخص سوم، اثرات رسانه یکدست و همگانی نیست، بلکه محدود و مشروط است. دبلیو. فیلیپس دیویسون (۱۹۸۳) تأکید کرد که فرد پیام را انفعالی دریافت نمی‌کند، بلکه بر اساس باورهای پیشین، انگیزه و اطلاعات در دسترس آن را پردازش می‌کند. قوت اثر رسانه به تناسب میان پیام و شرایط شناختی و انگیزشی مخاطب بستگی دارد و در بیشتر موارد، اثر در سطح «درباره‌ی چه چیزی فکر کنیم» و «چگونه به آن بنگریم» رخ می‌دهد، نه در سطح «به چه چیزی باور داشته باشیم».

اثر شخص سوم اثرات رسانه را فرایندی روان‌شناختی-اجتماعی می‌داند که در آن پیام، منبع و بستر اجتماعی با هم بر مخاطب اثر می‌گذارند. دبلیو. فیلیپس دیویسون (۱۹۸۳) مسیر شناختی و عاطفی که پیام از ادراک به تغییر نگرش را طی می‌کند تحلیل کرد و بر این نکته تأکید داشت که در فرایند اقناع، مقاومت، پادواژه‌سازی و بستر اجتماعی هم‌سنگِ خودِ محتوا اهمیت دارند.

۲. ساختارهای مفهومی
• مواجهه‌ی گزینشی (Selective Exposure): گرایشی که فرد را به انتخاب پیام‌های هم‌سو با باورهای پیشین خود سوق می‌دهد.
• پردازش شناختی (Cognitive Processing): عمق پردازش ذهنی پیام و نقش آن در ماندگاری تغییر نگرش.
• اعتبار منبع (Source Credibility): ادراک تخصص و اطمینان‌پذیری فرستنده و اثر آن بر اقناع.
• ترس‌افکنی (Fear Appeals): پیام‌هایی که ترس برانگیخت و اثر آن‌ها مشروط به ادراک کارآمدی راه‌حل است.
• دانش اقناع (Persuasion Knowledge): آگاهی مخاطب از ماهیت اقناعی پیام و بیدار شدن مقاومت در برابر آن.
• جریان دوشعویه (Two-Step Flow): انتقال اثر رسانه به مخاطبان ازطریق رهبران افکار و شبکه‌های بین‌فردی.
• وابستگی به رسانه (Media Dependency): درجه‌ای که مخاطب در شرایط مشخص', '6515bad5676b89b80915aa98887358a5f2f9644c4278ae6bf4dd8067d414718b', 2, NOW(), NOW()),
('sec-card-10-3', 'doc-card-10', 'components', 'اجزای نظری', 'نامتقارنی خود-دیگران؛ فاصله اجتماعی (Social Distance Corollary: هرچه «دیگران» دورتر، اثر ادراک‌شده بیشتر)؛ مطلوبیت اجتماعی پیام (در پیام‌های مطلوب ممکن است اثر «شخص اول» رخ دهد)؛ سوگیری خوش‌بینانه و خودبرتر‌بینی؛ حمایت از سانسور.', 'fd2c489364d04c26e2604f331c6388206220b2c0708c84e8b99a1f87d3c14f94', 3, NOW(), NOW()),
('sec-card-10-4', 'doc-card-10', 'applications', 'کاربردها', 'به رسانه به‌عنوان منبع جهت‌یابی تکیه می‌کند.
• قوت نگرش (Attitude Strength): میزان پایداری و مقاومت یک نگرش در برابر تغییر توسط پیام‌های جدید.

۳. نمونه‌های تحلیلی
در یک کمپین واکسیناسیون، انتخاب منبع قابل‌اعتماد (پزشک به‌جای مقام رسمی) و تأکید بر کارآمدی راه‌حل به‌جای ترس‌افکنی ساده، کاربرد عملی سازوکارهای اعتبار منبع و شرایط ترس‌افکنی است.

در انتخابات، نامزدهایی که هفته‌ها بر رویدادهای خبری و ترندهای شبکه‌های اجتماعی سلطه دارند، کوشش نمی‌کنند رأی‌دهندگان «به چه چیزی باور کنند»، بلکه موضوعی را به صدر دستور ذهنی رای‌دهندگان می‌برند؛ استراتژی‌ای مبتنی بر بُعد شناختی اثر رسانه.

فردی که باور دارد «اقتصاد خوب است»، هنگام مواجهه با ویدیویی وایرال از گران‌شدن، ابتدا تفسیرهای هم‌سو با باور خود را می‌جستجو و سپس نگرشش را تعدیل می‌کند؛ نمونه‌ای که در آن باورهای پیشین و پردازش گزینشی جهت اثر را تعیین می‌کند.

در شبکه‌های اجتماعی، پیام سیاسی که لایک و شریک‌کردن فراوان می‌گیرد، «اثبات اجتماعی» می‌سازد که اثر اقناعی آن را بر مخاطبان مردد بزرگ‌تر می‌کند، حتی اگر محتوایش تازه نباشد.

جوانی که مستند تغییر اقلیم می‌بیند ممکن است نگرشی کوتاه‌مدت بگیرد، اما اگر محیط اجتماعی او — خانواده، دوستان، محل کار — همان نگرش را نپذیرد، اثر در عرض چند هفته می‌خوابد؛ نمونه‌ی کلاسیک مشروط بودن اثر رسانه به بستر اجتماعی.

وقتی یک سلبریتی یک محصول را تأیید می‌کند، مخاطب بیشتر ازطریق دلبستگی عاطفی و ادراک شباهت با منبع تحت تأثیر قرار می‌گیرد تا ازطریق منطق استدلال؛ سازوکاری که در مسیر محیطی پردازش فعال می‌شود.

۴. نقدها و چالش‌ها
۱. مسئله اندازه‌ی اثر: آزمایش‌های آزمایشگاهی اغلب اثرهای کوچک و کوتاه‌مدت نشان می‌دهند، درحالی‌که در شرایط میدانی واقعی (مانند انتخابات) اثرها بزرگ‌تر و ماندگارتر به نظر می‌رسند؛ جمع‌بندی این دو مجموعه یافته دشوار است.
۲. جهت علیت: اثبات اینکه رسانه نگرش را تغییر داده است — نه اینکه فرد بر اساس نگرش پیشین رسانه‌اش را انتخاب کرده — به‌دلیل مواجهه‌ی گزینشی بسیار دشوار است.
۳. فرهنگی‌بودن نمونه‌ها: بیشتر یافته‌های کلاسیک از نمونه‌های غربی و فردگرا گرفته شده‌اند و قابلیت تعم', 'afaddecaf8e1e941a4a733706391b35837299af0b82c7e40be9a71c7d1260e8c', 4, NOW(), NOW()),
('sec-card-10-5', 'doc-card-10', 'examples', 'مثال‌ها', 'بحث‌های اخبار جعلی، دیپ‌فیک و محتوای نفرت‌پراکن: کاربران معمولاً می‌گویند «من فریب نمی‌خورم، اما دیگران می‌خورند» و این باور به حمایت از ناظرسازی محتوا، حذف خودکار یا قانون‌گذاری پلتفرم‌ها گره می‌خورد. در مدیریت رسانه، همین ادراک بر مطالبه تنظیم‌گری اثر می‌گذارد.', 'ba9ac944bbe3e31a3366ef46236bdf9bc0d15963e09dd4ad942ec7abf26301e0', 5, NOW(), NOW()),
('sec-card-10-6', 'doc-card-10', 'criticism', 'نقدها', 'پژوهش‌ها (Perloff، ۱۹۹۹؛ فراتحلیل Sun, Pan & Shen، ۲۰۰۸) مؤلفه ادراکی را پایدار نشان داده‌اند اما شواهد مؤلفه رفتاری ناهمگن است. ادراک بر پایه خودگزارشی سنجیده می‌شود و ممکن است نتیجه سوگیری روش‌شناختی یا مطلوبیت اجتماعی باشد، نه واقعیت اثر.', '9db72308f0efec3ca197559b709980bf6c50c5e800bd8d14e79d30d2d545d94c', 6, NOW(), NOW()),
('sec-card-10-10', 'doc-card-10', 'references', 'منابع', 'استناد علمی مبنا (APA 7): Davison (1983)', 'e0423045cdb3b561ea661407df271ac06431bc958861a4157ec3a334257ac959', 10, NOW(), NOW());
