-- card-100: جوامع تصوری
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`) VALUES
('doc-card-100', 'card', 'card-100', 'mc-100', 'جوامع تصوری', 'Imagined Communities', 'theory', 'ملت جامعه‌ای «تصوری» است، چون اعضا هرگز همه یکدیگر را نمی‌شناسند ولی تصویر هم‌پیوندی در ذهن دارند. اندرسون «سرمایه‌داری چاپی» را عامل مهم شکل‌گیری آن می‌داند: روزنامه و رمان به خوانندگان پراکنده حس زمان همگون و هم‌زمانی می‌دادند.', 'https://resaname.ir/cards/card-100', 'fa', NULL, NULL, '6ad1b8d643604b340807b95ffb0b02508cc58ed0c9749047e8123b8fb01bc8f9', '2026-10-14 01:36:04', NOW());
INSERT INTO `ai_document_sections` (`id`, `document_id`, `section_key`, `section_title`, `content`, `content_hash`, `sort_order`, `created_at`, `updated_at`) VALUES
('sec-card-100-1', 'doc-card-100', 'definition', 'تعریف', 'مطالعات ملی‌گرایی / تاریخ رسانه

ملت جامعه‌ای «تصوری» است، چون اعضا هرگز همه یکدیگر را نمی‌شناسند ولی تصویر هم‌پیوندی در ذهن دارند. اندرسون «سرمایه‌داری چاپی» را عامل مهم شکل‌گیری آن می‌داند: روزنامه و رمان به خوانندگان پراکنده حس زمان همگون و هم‌زمانی می‌دادند.', 'c187ffe4873760fe6ca6eae3ce31811e5745bcc46fb36bed89b97860e5e0c0ff', 1, NOW(), NOW()),
('sec-card-100-2', 'doc-card-100', 'theoretical_framework', 'چارچوب نظری', '۱. بنیان و منطق نظری
جوامع تصوری رسانه را نه «آینه‌ی» جامعه بلکه «میدان» تولید و بازتولید قدرت می‌داند. بندیکت اندرسون (۱۹۸۳) در این چارچوب، پرسش بنیادین از «رسانه چه می‌کند؟» به «رسانه برای چه کسی و با کدام منافع؟» تبدیل می‌شود؛ رسانه، نهادی اجتماعی است که در «موقعیت معینی» در ساختارهای مالکیت، سرمایه و حاکمیت قرار دارد.

بر اساس جوامع تصوری، «انتقادی» بودن به معنای رد «توصیف» و رسیدن به «ریشه» است: بندیکت اندرسون (۱۹۸۳) نشان داد که «فرهنگ عامه» و «صنعت سرگرمی» نه پدیده‌های بی‌ضرر، بلکه «صحنه‌هایی»اند که در آن‌ها ایدئولوژی و سلسله‌مراتب اجتماعی بازتولید می‌شوند. این چارچوب در سطح خرد تحلیل، رسانه را به «سازوکار ایدئولوژیک» ارتقا می‌دهد.

جوامع تصوری را می‌توان پاسخی به شکاف میان «مکتب کارکردی-اجماعی» (رسانه به‌عنوان خدمت) و «مکتب کارکردی» (رسانه به‌عنوان ابزار ثبات) دانست: مکتب انتقادی می‌پرسد «چه ناهنجاری‌هایی پنهان‌اند؟». بندیکت اندرسون (۱۹۸۳) در این چارچوب، «آگاهی انتقادی» را هدف نهایی تحلیل رسانه قرار داد: هدف، «آزادسازی» مخاطب از خودفریفتگی است.

۲. ساختارهای مفهومی
• مکتب فرانکفورت (Frankfurt School): نقد «صنعت فرهنگ»؛ رسانه‌ی تجاری، ایدئولوژی را به‌صورت سرگرمی بازتولید می‌کند و منتقد، حافظه‌ی آزادی را زنده نگه می‌دارد.
• اقتصادسیاست رسانه (Political Economy): مالکیت، تمرکز و جریان سرمایه، «محتوا» را از پیش تعیین می‌کنند؛ پرسش «چه کسی مالک است؟» نخستین پرسش تحلیل است.
• مطالعات فرهنگی (Cultural Studies): «مخاطب» و «بازنمایی» در کانون؛ قدرت در «معنا» عمل می‌کند و فرهنگ، میدان نبرد معنایی است.
• ایدئولوژی (Ideology): نظام معنایی حاکم که «طبیعی» به نظر می‌رسد؛ کار رسانه، این «طبیعی‌نمایی» است و کار تحلیل، «تاریخی‌سازی» آن.
• خودفریفتگی (False Consciousness): پذیرش ناهنجاری اجتماعی به‌عنوان «طبیعی» یا «ضروری»؛ رسانه با فرمت سرگرمی، این پذیرش را عمیق‌تر می‌کند.', 'c188fe040d1e85420484ae03cbd843300ce98e5d8717d24c9fc6312fdc9bf1b8', 2, NOW(), NOW()),
('sec-card-100-3', 'doc-card-100', 'components', 'اجزای نظری', 'ملت؛ سرمایه‌داری چاپی؛ زبان‌های بومی؛ زمان همگون و تهی؛ هم‌زمانی؛ هم‌رفاقت افقی.', '7694aa7c6e4640984167e7cc4706cbec7d9e6554d26918f417110722f0d0ee1e', 3, NOW(), NOW()),
('sec-card-100-4', 'doc-card-100', 'applications', 'کاربردها', '• بازنمایی (Representation): «واقعیت» از طریق «نماد» می‌آید و نمادگذاری، انتخاب سیاسی است؛ چه کسی «نمایش» می‌یابد و چگونه؟
• صنعت فرهنگ (Culture Industry): تولید کالاهای فرهنگی به‌منطق سود؛ تکرار، استاندارد و مصرف‌پذیری، ویژگی ساختاری آن‌اند.
• آگاهی انتقادی (Critical Consciousness): توانایی خواندن «ریشه» پدیده‌ها؛ هدف نهایی مکتب انتقادی، گذار از «مخاطب فریب‌خورده» به «مواظب بیدار» است.

۳. نمونه‌های تحلیلی
وقتی مکتب فرانکفورت به یک «سریال خانوادگی» نگاه می‌کند، نمی‌پرسد «چه پیامی دارد؟» بلکه می‌پرسد «این سریال، کدام روابط اجتماعی را طبیعی می‌نماید و کدام‌ها را نامرئی می‌کند؟» — «عادی‌نمایی» همان «ایدئولوژی» است.

«اقتصادسیاست» با یک پرسش ساده شروع می‌کند: «چه کسی صاحب این شبکه است و از کجا درآمد می‌آورد؟» — پاسخ، «محتوا» را از پیش توضیح می‌دهد، بدون آنکه وارد «متن» شود.

«مطالعات فرهنگی» به «میم» و «ریپلای» نگاه می‌کند و می‌بیند که «مخاطب» در موضع «تفسیر» و حتی «مقاومت» قرار دارد: قدرت صرفا از بالا نمی‌آید، بلکه در «معامله‌ی معنایی» بازتولید می‌شود.

«ایدئولوژی» در عمل: وقتی اخبار، «فقر» را «کم‌کاری فردی» می‌خواند، ایدئولوژی «فعل» است؛ تحلیل انتقادی این «طبیعی» را «تاریخی» می‌کند و نشان می‌دهد چگونه شکل گرفته است.

«صنعت فرهنگ» در «پلتفرم‌های استریمینگ»: «تم‌های» تولیدی، «الگوریتم» و «فصل‌بندی» سریال‌ها، «استاندارد» و «تکرار» را به‌منطق سود می‌سازند.

«آگاهی انتقادی» در عمل: مخاطبی که می‌داند «فید» او توسط «الگوریتم» چیده شده و «دیدگاه» او به «داده» تبدیل شده، در وضعیت «انتخاب آگاهانه» است، نه «تلقی».

۴. نقدها و چالش‌ها
۱. «انتقادی‌باشی» به‌عنوان موضع، گاه به «مبانی‌گری» تبدیل می‌شود: تحلیل از پیش‌فرض «انتقادی» شروع می‌شود و داده، تأیید موضع می‌شود.
۲. «مخاطب» در مکاتب انتقادی کماکان «منفعل» ترسیم می‌شود: «ایدئولوژی» و «صنعت فرهنگ» بر «تلقین» تأکید دارند و «عا', 'e534858231148750c6eca7ee51d4b9b1a5e9ca79ed6a62f3ad6153df8ee80317', 4, NOW(), NOW()),
('sec-card-100-5', 'doc-card-100', 'examples', 'مثال‌ها', 'بررسی اینکه شبکه‌های اجتماعی و جوامع آنلاین چگونه هویت‌های فراملی یا خرده‌ملی تصوری می‌سازند.', 'f7a3ff4255a0f13dc177dcd049e9f0d7a3edf5c114c91b5ffb78b27f102c5c77', 5, NOW(), NOW()),
('sec-card-100-6', 'doc-card-100', 'criticism', 'نقدها', 'منتقدان (از جمله پارتا چترجی) می‌گویند الگوی اندرسون ملی‌گرایی را اروپامحور توضیح می‌دهد و تجربه استعمارزدایی را نادیده می‌گیرد. نقش رسانه به‌عنوان علت نیز بیش از حد تعمیم یافته است.', '8e2592d5a3e1e61701831491282cea9daa2fb4dac70b1739863ea7b7c4d5dc97', 6, NOW(), NOW()),
