-- card-101: اثر رسانه خصمانه
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`) VALUES
('doc-card-101', 'card', 'card-101', 'mc-101', 'اثر رسانه خصمانه', 'Hostile Media Effect', 'effect', 'افراد با نگرش قوی و درگیری بالا درباره موضوعی، یک پوشش خبری یکسان را علیه موضع خود ارزیابی می‌کنند؛ طرفداران دو سوی مناقشه هر دو آن را سوگیرانه می‌بینند. توضیح‌های رایج شامل ادراک گزینشی و دسته‌بندی گزینشی است.', 'https://resaname.ir/cards/card-101', 'fa', NULL, NULL, '6488652f35b230a7ce6dfe291e303c931ef770052b47740384f8a5ec9eda6ac8', '2026-10-14 01:36:03', NOW());
INSERT INTO `ai_document_sections` (`id`, `document_id`, `section_key`, `section_title`, `content`, `content_hash`, `sort_order`, `created_at`, `updated_at`) VALUES
('sec-card-101-1', 'doc-card-101', 'definition', 'تعریف', 'روان‌شناسی اجتماعی رسانه / ادراک سوگیری

افراد با نگرش قوی و درگیری بالا درباره موضوعی، یک پوشش خبری یکسان را علیه موضع خود ارزیابی می‌کنند؛ طرفداران دو سوی مناقشه هر دو آن را سوگیرانه می‌بینند. توضیح‌های رایج شامل ادراک گزینشی و دسته‌بندی گزینشی است.', '053b25e2f64acf9f2cf88f5f7d8bd8c5b07db5762b06ed660b5bc9355f0d1446', 1, NOW(), NOW()),
('sec-card-101-2', 'doc-card-101', 'theoretical_framework', 'چارچوب نظری', '۱. بنیان و منطق نظری
اثر رسانه خصمانه رسانه را بر ذهن و رفتار انسان ازطریق سازوکارهای روان‌شناختی می‌خواند: توجه، یادگیری، هیجان و خودتصویر. والون (۱۹۸۵) نشان داد که اثرات رسانه نه صرفاَ در «محتوا» بلکه در سازوکارهای شناختی و عاطفی است که پیام در ذهن مخاطب فعال می‌کند. این چارچوب در سطح میانی تحلیل، رسانه را با آزمایش و اندازه‌گیری روان‌شناختی می‌سنجد.

بر اساس اثر رسانه خصمانه، مواجهه با رسانه فرایند روان‌شناختی‌ای است با ورودی (پیام)، پردازش (توجه، تفسیر، یادگیری) و خروجی (نگرش، هیجان، رفتار). والون (۱۹۸۵) این فرایند را در آزمایش‌های کنترل‌شده مطالعه کرد تا نشان دهد چه نوع پیامی، در چه شرایطی، چه اثری می‌گذارد و این اثر چقدر پایدار است.

اثر رسانه خصمانه رسانه را بومی «شناختی-عاطفی» انسان می‌داند: رسانه توجه ما را می‌گیرد، هیجان‌هایمان را می‌راند و تصویر خودمان را شکل می‌دهد. والون (۱۹۸۵) در این چارچوب، از یادگیری اجتماعی تا خودتنظیمی هیجانی، سازوکارهایی را تحلیل کرد که تجربه‌ی رسانه‌ای — از خبر تا بازی ویدیویی — را به تجربه‌ی روان‌شناختی تبدیل می‌کند.

۲. ساختارهای مفهومی
• یادگیری اجتماعی (Social Learning): فرایند یادگیری رفتار ازطریق مشاهده الگوهای رسانه‌ای و الگوبرداری از آن‌ها.
• تعامل پاراسوشال (Parasocial Interaction): رابطه‌ی یک‌سویه و ذهنی میان مخاطب و شخصیت رسانه‌ای که ازطریق تکرار تقویت می‌شود.
• مقایسه اجتماعی (Social Comparison): فرایند داوری خود بر اساس مقایسه با الگوهای رسانه‌ای؛ غالباً به‌سمت بالایی و با پیامدهای منفی.
• مدیریت خلق (Mood Management): استفاده‌ی هدفمند از رسانه برای تنظیم و بهبود حالت عاطفی.
• انتقال برانگیختگی (Arousal Transfer): جابه‌جایی هیجان ایجادشده (ترس، هیجان) به اشیاء یا افراد پیرامونی.
• حساسیت‌زایی (Sensitization) و بیهودساز (Desensitization): افزایش و کاهش پاسخ عاطفی به محرک‌ها ازطریق مواجهه‌ی مکرر.
• پردازش', '7174d86e8f06283d8bff0e8c705cf0d9158f67f44fd781078533c675d2cdbda7', 2, NOW(), NOW()),
('sec-card-101-3', 'doc-card-101', 'components', 'اجزای نظری', 'درگیری و هویت گروهی؛ نگرش پیشین؛ ادراک سوگیری؛ ادراک جو افکار؛ بی‌اعتمادی به رسانه.', '45c3eb63f60ea152f39be90e1050e6f52ae2ea469f3d66139b48151836d4c2cf', 3, NOW(), NOW()),
('sec-card-101-4', 'doc-card-101', 'applications', 'کاربردها', 'محدود (Limited Capacity): ظرفیت محدود توجه و پردازش ذهن که رسانه آن را «مبارزه» می‌کند.
• خودتنظیمی رسانه‌ای (Self-Regulation): توانایی فرد در مدیریت مصرف و اثرات رسانه در طول زمان.

۳. نمونه‌های تحلیلی
یک نوجوان که بارها صحنه‌های خشونت‌آمیز در بازی‌های ویدیویی را می‌بیند، با سازوکار «یادگیری اجتماعی» و «بیهودساز» هم‌زمان روبه‌رو است: هم الگوهای رفتاری می‌آموزد و هم پاسخ عاطفی‌اش نسبت به خشونت کاهش می‌یابد.

وقتی یک فرد پس از دیدن یک مستند ترسناک، به آسان‌تر «عصبانی» شدن یا «ترسیدن» از محیط اطرافش می‌رسد، نمونه‌ای از «انتقال برانگیختگی» است: هیجان ایجادشده در رسانه، به واقعیت بیرون منتقل شده است.

مخاطبی که هر شب به‌جای خواب، سریال می‌بیند تا از اضطراب روزمره فرار کند، در عمل «مدیریت خلق» انجام می‌دهد — رسانه به‌عنوان ابزار خودتنظیمی هیجانی.

وقتی یک نوجوان خود را با «تصاویر بدنی» در اینستاگرام مقایسه می‌کند و احساس ناکافی بودن می‌کند، سازوکار «مقایسه اجتماعی به‌سمت بالایی» در جریان است؛ بازنمایی رسانه‌ای، معیار داوری خود را تعیین کرده است.

یک هوادار فوتبال که پس از دیدن بازی تیمش، در خیابان «هیجان» خود را به غریبه‌ها منتقل می‌کند، نمونه‌ی عملی «انتقال برانگیختگی» است.

وقتی یک کودک پس از تماشای انیمیشن، رفتار شخصیت آن را تقلید می‌کند، «یادگیری اجتماعی» در ساده‌ترین شکل خود آشکار است: مشاهده، به یادگیری و به رفتار تبدیل شده است.

۴. نقدها و چالش‌ها
۱. مسئله‌ی مقیاس اثر: بسیاری از یافته‌های آزمایشگاهی (مانند اثرات خشونت) در شرایط کنترل‌شده مشاهده شده‌اند و تعمیم آن‌ها به مواجهه‌ی روزمره‌ی واقعی (که با هزاران پیام و بافت همراه است) دشوار است.
۲. جهت علیت: اثبات اینکه رسانه علت تغییر رفتار است — نه اینکه افراد با رفتار خاص، رسانه‌های خاص را انتخاب می‌کنند — به‌دلیل انتخاب‌گری مخاطب مشکل است.
۳. ریسک «بچه‌بندی» مخاطب: مدل‌های روان‌شناختی گاه مخاطب را «موجود', '24e32df9954265071f135698585c28791a0c0f4f1d2749c069de7a7ada180f87', 4, NOW(), NOW()),
('sec-card-101-5', 'doc-card-101', 'examples', 'مثال‌ها', 'تحلیل اینکه چرا طرفداران دو طرف یک مناقشه سیاسی، گزارش واحد یک رسانه را جانبدار می‌دانند و چه اثری بر اعتماد به رسانه دارد.', 'b3e6ccc39dace9e01095ef82a1c07e7ab9ba2e80b0c99c4626f1ca10e10f9c87', 5, NOW(), NOW()),
('sec-card-101-6', 'doc-card-101', 'criticism', 'نقدها', 'اثر در همه موضوعات و برای همه مخاطبان یکسان نیست و به بافت و ویژگی منبع بستگی دارد. تفکیک سوگیری واقعی پوشش از ادراک سوگیری دشوار است.', '6223c462c7b1e07286a944c75a88d5a8e1bc1181dd757df2f98abb7c123f34f3', 6, NOW(), NOW()),
('sec-card-101-10', 'doc-card-101', 'references', 'منابع', 'کتاب «یادگیری اجتماعی» (آلبرت بندورا، ۱۹۷۷)؛ کتاب «اثرات رسانه‌ای» (گربنر و همکاران، ۱۹۸۶)؛ کتاب «روان‌شناسی رسانه» (مک‌کوایل، ۱۹۸۳)؛ استناد مبنا: Bandura (1977) بر یادگیری اجتماعی.', '43a9bf562b10592fe44e9bf42f1da33afaaed8186bcec99d815963196e193dd9', 10, NOW(), NOW());
