INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`) VALUES
('doc-card-102', 'card', 'card-102', 'mc-102', 'تعامل پاراسوشیال', 'Parasocial Interaction', 'theory', 'مخاطب با شخصیت رسانه‌ای (مجری، سلبریتی، اینفلوئنسر) رابطه‌ای به‌ظاهر رودررو و صمیمی شکل می‌دهد، هرچند رابطه یک‌سویه است. تکرار مواجهه و شیوه خطاب مستقیم این احساس آشنایی را تقویت می‌کند.', 'https://resaname.ir/cards/card-102', 'fa', NULL, NULL, 'f071fbac3833b721d3c78979edb529a3d9922009a47f14c29656e202ed93a632', '2026-10-14 01:36:04', NOW());
INSERT INTO `ai_document_sections` (`id`, `document_id`, `section_key`, `section_title`, `content`, `content_hash`, `sort_order`, `created_at`, `updated_at`) VALUES
('sec-card-102-1', 'doc-card-102', 'definition', 'تعریف', 'روان‌شناسی رسانه / مطالعات سلبریتی و اینفلوئنسر

مخاطب با شخصیت رسانه‌ای (مجری، سلبریتی، اینفلوئنسر) رابطه‌ای به‌ظاهر رودررو و صمیمی شکل می‌دهد، هرچند رابطه یک‌سویه است. تکرار مواجهه و شیوه خطاب مستقیم این احساس آشنایی را تقویت می‌کند.', 'e7cb4e27edbc1fb4db891cd5447e4b395e2d4e8393c81c00150178343c80b98e', 1, NOW(), NOW()),
('sec-card-102-2', 'doc-card-102', 'theoretical_framework', 'چارچوب نظری', '۱. بنیان و منطق نظری
تعامل پاراسوشیال رسانه را بر ذهن و رفتار انسان ازطریق سازوکارهای روان‌شناختی می‌خواند: توجه، یادگیری، هیجان و خودتصویر. دونالد هورتن (۱۹۵۶) نشان داد که اثرات رسانه نه صرفاَ در «محتوا» بلکه در سازوکارهای شناختی و عاطفی است که پیام در ذهن مخاطب فعال می‌کند. این چارچوب در سطح خرد تحلیل، رسانه را با آزمایش و اندازه‌گیری روان‌شناختی می‌سنجد.

بر اساس تعامل پاراسوشیال، مواجهه با رسانه فرایند روان‌شناختی‌ای است با ورودی (پیام)، پردازش (توجه، تفسیر، یادگیری) و خروجی (نگرش، هیجان، رفتار). دونالد هورتن (۱۹۵۶) این فرایند را در آزمایش‌های کنترل‌شده مطالعه کرد تا نشان دهد چه نوع پیامی، در چه شرایطی، چه اثری می‌گذارد و این اثر چقدر پایدار است.

تعامل پاراسوشیال رسانه را بومی «شناختی-عاطفی» انسان می‌داند: رسانه توجه ما را می‌گیرد، هیجان‌هایمان را می‌راند و تصویر خودمان را شکل می‌دهد. دونالد هورتن (۱۹۵۶) در این چارچوب، از یادگیری اجتماعی تا خودتنظیمی هیجانی، سازوکارهایی را تحلیل کرد که تجربه‌ی رسانه‌ای — از خبر تا بازی ویدیویی — را به تجربه‌ی روان‌شناختی تبدیل می‌کند.

۲. ساختارهای مفهومی
• یادگیری اجتماعی (Social Learning): فرایند یادگیری رفتار ازطریق مشاهده الگوهای رسانه‌ای و الگوبرداری از آن‌ها.
• تعامل پاراسوشال (Parasocial Interaction): رابطه‌ی یک‌سویه و ذهنی میان مخاطب و شخصیت رسانه‌ای که ازطریق تکرار تقویت می‌شود.
• مقایسه اجتماعی (Social Comparison): فرایند داوری خود بر اساس مقایسه با الگوهای رسانه‌ای؛ غالباً به‌سمت بالایی و با پیامدهای منفی.
• مدیریت خلق (Mood Management): استفاده‌ی هدفمند از رسانه برای تنظیم و بهبود حالت عاطفی.
• انتقال برانگیختگی (Arousal Transfer): جابه‌جایی هیجان ایجادشده (ترس، هیجان) به اشیاء یا افراد پیرامونی.
• حساسیت‌زایی (Sensitization) و بیهودساز (Desensitization): افزایش و کاهش پاسخ عاطفی به محرک‌ها ازطریق مواجهه‌ی مکر', 'fab1ba57eb19c31276740d385a81ae4f4028c5f779292737e769b2c662d07521', 2, NOW(), NOW()),
('sec-card-102-3', 'doc-card-102', 'components', 'اجزای نظری', 'یک‌سویه‌بودن رابطه؛ خطاب مستقیم؛ همانندسازی؛ شباهت ادراک‌شده؛ تعهد؛ اعتماد.', 'cfaea759a37de92db5a27312da7b57ff3c6b17285ccb67661f227c2ef2b27f9a', 3, NOW(), NOW()),
('sec-card-102-4', 'doc-card-102', 'applications', 'کاربردها', 'ر.
• پردازش محدود (Limited Capacity): ظرفیت محدود توجه و پردازش ذهن که رسانه آن را «مبارزه» می‌کند.
• خودتنظیمی رسانه‌ای (Self-Regulation): توانایی فرد در مدیریت مصرف و اثرات رسانه در طول زمان.

۳. نمونه‌های تحلیلی
یک نوجوان که بارها صحنه‌های خشونت‌آمیز در بازی‌های ویدیویی را می‌بیند، با سازوکار «یادگیری اجتماعی» و «بیهودساز» هم‌زمان روبه‌رو است: هم الگوهای رفتاری می‌آموزد و هم پاسخ عاطفی‌اش نسبت به خشونت کاهش می‌یابد.

وقتی یک فرد پس از دیدن یک مستند ترسناک، به آسان‌تر «عصبانی» شدن یا «ترسیدن» از محیط اطرافش می‌رسد، نمونه‌ای از «انتقال برانگیختگی» است: هیجان ایجادشده در رسانه، به واقعیت بیرون منتقل شده است.

مخاطبی که هر شب به‌جای خواب، سریال می‌بیند تا از اضطراب روزمره فرار کند، در عمل «مدیریت خلق» انجام می‌دهد — رسانه به‌عنوان ابزار خودتنظیمی هیجانی.

وقتی یک نوجوان خود را با «تصاویر بدنی» در اینستاگرام مقایسه می‌کند و احساس ناکافی بودن می‌کند، سازوکار «مقایسه اجتماعی به‌سمت بالایی» در جریان است؛ بازنمایی رسانه‌ای، معیار داوری خود را تعیین کرده است.

یک هوادار فوتبال که پس از دیدن بازی تیمش، در خیابان «هیجان» خود را به غریبه‌ها منتقل می‌کند، نمونه‌ی عملی «انتقال برانگیختگی» است.

وقتی یک کودک پس از تماشای انیمیشن، رفتار شخصیت آن را تقلید می‌کند، «یادگیری اجتماعی» در ساده‌ترین شکل خود آشکار است: مشاهده، به یادگیری و به رفتار تبدیل شده است.

۴. نقدها و چالش‌ها
۱. مسئله‌ی مقیاس اثر: بسیاری از یافته‌های آزمایشگاهی (مانند اثرات خشونت) در شرایط کنترل‌شده مشاهده شده‌اند و تعمیم آن‌ها به مواجهه‌ی روزمره‌ی واقعی (که با هزاران پیام و بافت همراه است) دشوار است.
۲. جهت علیت: اثبات اینکه رسانه علت تغییر رفتار است — نه اینکه افراد با رفتار خاص، رسانه‌های خاص را انتخاب می‌کنند — به‌دلیل انتخاب‌گری مخاطب مشکل است.
