-- card-106: مدل عمومی پرخاشگری
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`) VALUES
('doc-card-106', 'card', 'card-106', 'mc-106', 'مدل عمومی پرخاشگری', 'General Aggression Model', 'model', 'عوامل فردی و موقعیتی (از جمله مواجهه با خشونت رسانه‌ای) از طریق شناخت، عواطف و برانگیختگی بر ارزیابی و تصمیم تأثیر می‌گذارند و می‌توانند احتمال پرخاشگری را افزایش دهند. مواجهه مکرر می‌تواند از طریق یادگیری، دانش‌ساخت‌های پرخاشگرانه را تقویت کند.', 'https://resaname.ir/cards/card-106', 'fa', NULL, NULL, '5777160a936bfbb1df284eeb332a62de0976237a75417a5be6fbb00b0dc1c6a6', '2026-10-14 01:36:04', NOW());
INSERT INTO `ai_document_sections` (`id`, `document_id`, `section_key`, `section_title`, `content`, `content_hash`, `sort_order`, `created_at`, `updated_at`) VALUES
('sec-card-106-1', 'doc-card-106', 'definition', 'تعریف', 'روان‌شناسی اجتماعی / پژوهش بازی ویدئویی

عوامل فردی و موقعیتی (از جمله مواجهه با خشونت رسانه‌ای) از طریق شناخت، عواطف و برانگیختگی بر ارزیابی و تصمیم تأثیر می‌گذارند و می‌توانند احتمال پرخاشگری را افزایش دهند. مواجهه مکرر می‌تواند از طریق یادگیری، دانش‌ساخت‌های پرخاشگرانه را تقویت کند.', '2e01e8a21b4308a9036edb4c3ad3f386fcafb0751bbb1eceb8f0059d9c5aaeaa', 1, NOW(), NOW()),
('sec-card-106-2', 'doc-card-106', 'theoretical_framework', 'چارچوب نظری', '۱. بنیان و منطق نظری
مدل عمومی پرخاشگری رسانه را بر ذهن و رفتار انسان ازطریق سازوکارهای روان‌شناختی می‌خواند: توجه، یادگیری، هیجان و خودتصویر. اندرسون (۲۰۰۲) نشان داد که اثرات رسانه نه صرفاَ در «محتوا» بلکه در سازوکارهای شناختی و عاطفی است که پیام در ذهن مخاطب فعال می‌کند. این چارچوب در سطح خرد تحلیل، رسانه را با آزمایش و اندازه‌گیری روان‌شناختی می‌سنجد.

بر اساس مدل عمومی پرخاشگری، مواجهه با رسانه فرایند روان‌شناختی‌ای است با ورودی (پیام)، پردازش (توجه، تفسیر، یادگیری) و خروجی (نگرش، هیجان، رفتار). اندرسون (۲۰۰۲) این فرایند را در آزمایش‌های کنترل‌شده مطالعه کرد تا نشان دهد چه نوع پیامی، در چه شرایطی، چه اثری می‌گذارد و این اثر چقدر پایدار است.

مدل عمومی پرخاشگری رسانه را بومی «شناختی-عاطفی» انسان می‌داند: رسانه توجه ما را می‌گیرد، هیجان‌هایمان را می‌راند و تصویر خودمان را شکل می‌دهد. اندرسون (۲۰۰۲) در این چارچوب، از یادگیری اجتماعی تا خودتنظیمی هیجانی، سازوکارهایی را تحلیل کرد که تجربه‌ی رسانه‌ای — از خبر تا بازی ویدیویی — را به تجربه‌ی روان‌شناختی تبدیل می‌کند.

۲. ساختارهای مفهومی
• یادگیری اجتماعی (Social Learning): فرایند یادگیری رفتار ازطریق مشاهده الگوهای رسانه‌ای و الگوبرداری از آن‌ها.
• تعامل پاراسوشال (Parasocial Interaction): رابطه‌ی یک‌سویه و ذهنی میان مخاطب و شخصیت رسانه‌ای که ازطریق تکرار تقویت می‌شود.
• مقایسه اجتماعی (Social Comparison): فرایند داوری خود بر اساس مقایسه با الگوهای رسانه‌ای؛ غالباً به‌سمت بالایی و با پیامدهای منفی.
• مدیریت خلق (Mood Management): استفاده‌ی هدفمند از رسانه برای تنظیم و بهبود حالت عاطفی.
• انتقال برانگیختگی (Arousal Transfer): جابه‌جایی هیجان ایجادشده (ترس، هیجان) به اشیاء یا افراد پیرامونی.
• حساسیت‌زایی (Sensitization) و بیهودساز (Desensitization): افزایش و کاهش پاسخ عاطفی به محرک‌ها ازطریق مواجهه‌ی مکرر.
• پ', 'a8ad2e42af13be7b5b187037bae5c23a45bddc579123c5b004082a6f91639157', 2, NOW(), NOW()),
('sec-card-106-3', 'doc-card-106', 'components', 'اجزای نظری', 'متغیرهای شخصی و موقعیتی؛ حالت درونی (شناخت، عاطفه، برانگیختگی)؛ ارزیابی و تصمیم؛ دانش‌ساخت‌ها؛ مواجهه مکرر.', '7313477124067f0889f1b21b5527a2bb4b6545e65baab7984a34dd73218a56eb', 3, NOW(), NOW()),
('sec-card-106-4', 'doc-card-106', 'applications', 'کاربردها', 'ردازش محدود (Limited Capacity): ظرفیت محدود توجه و پردازش ذهن که رسانه آن را «مبارزه» می‌کند.
• خودتنظیمی رسانه‌ای (Self-Regulation): توانایی فرد در مدیریت مصرف و اثرات رسانه در طول زمان.

۳. نمونه‌های تحلیلی
یک نوجوان که بارها صحنه‌های خشونت‌آمیز در بازی‌های ویدیویی را می‌بیند، با سازوکار «یادگیری اجتماعی» و «بیهودساز» هم‌زمان روبه‌رو است: هم الگوهای رفتاری می‌آموزد و هم پاسخ عاطفی‌اش نسبت به خشونت کاهش می‌یابد.

وقتی یک فرد پس از دیدن یک مستند ترسناک، به آسان‌تر «عصبانی» شدن یا «ترسیدن» از محیط اطرافش می‌رسد، نمونه‌ای از «انتقال برانگیختگی» است: هیجان ایجادشده در رسانه، به واقعیت بیرون منتقل شده است.

مخاطبی که هر شب به‌جای خواب، سریال می‌بیند تا از اضطراب روزمره فرار کند، در عمل «مدیریت خلق» انجام می‌دهد — رسانه به‌عنوان ابزار خودتنظیمی هیجانی.

وقتی یک نوجوان خود را با «تصاویر بدنی» در اینستاگرام مقایسه می‌کند و احساس ناکافی بودن می‌کند، سازوکار «مقایسه اجتماعی به‌سمت بالایی» در جریان است؛ بازنمایی رسانه‌ای، معیار داوری خود را تعیین کرده است.

یک هوادار فوتبال که پس از دیدن بازی تیمش، در خیابان «هیجان» خود را به غریبه‌ها منتقل می‌کند، نمونه‌ی عملی «انتقال برانگیختگی» است.

وقتی یک کودک پس از تماشای انیمیشن، رفتار شخصیت آن را تقلید می‌کند، «یادگیری اجتماعی» در ساده‌ترین شکل خود آشکار است: مشاهده، به یادگیری و به رفتار تبدیل شده است.

۴. نقدها و چالش‌ها
۱. مسئله‌ی مقیاس اثر: بسیاری از یافته‌های آزمایشگاهی (مانند اثرات خشونت) در شرایط کنترل‌شده مشاهده شده‌اند و تعمیم آن‌ها به مواجهه‌ی روزمره‌ی واقعی (که با هزاران پیام و بافت همراه است) دشوار است.
۲. جهت علیت: اثبات اینکه رسانه علت تغییر رفتار است — نه اینکه افراد با رفتار خاص، رسانه‌های خاص را انتخاب می‌کنند — به‌دلیل انتخاب‌گری مخاطب مشکل است.
۳. ریسک «بچه‌بندی» مخاطب: مدل‌های روان‌شناختی گاه مخاطب را «موج', 'd897e3e3c7b6075e8aae2ebae0c478b114da5c197b6d6a7ebad0d1d1666c8b1a', 4, NOW(), NOW()),
('sec-card-106-5', 'doc-card-106', 'examples', 'مثال‌ها', 'طراحی پژوهشی درباره اثر بازی‌های خشن بر نگرش‌های پرخاشگرانه، با کنترل ویژگی‌های شخصیتی و محیطی.', 'dff51b800628508e7d755b7dd980e77c305e267956d857e6173fa497aa6ae5df', 5, NOW(), NOW()),
('sec-card-106-6', 'doc-card-106', 'criticism', 'نقدها', 'اندازه اثر و کیفیت سنجش پرخاشگری محل بحث است و برخی فراتحلیل‌ها و پژوهشگران (مانند فرگوسن) اثر را ناچیز می‌دانند. اثر آزمایشگاهی لزوماً به خشونت واقعی تعمیم نمی‌یابد.', '83a80506eddbdc110aa305f8aa75d2cea536190cc8cbc8acee26663bbaff5031', 6, NOW(), NOW()),
('sec-card-106-10', 'doc-card-106', 'references', 'منابع', 'کتاب «یادگیری اجتماعی» (آلبرت بندورا، ۱۹۷۷)؛ کتاب «اثرات رسانه‌ای» (گربنر و همکاران، ۱۹۸۶)؛ کتاب «روان‌شناسی رسانه» (مک‌کوایل، ۱۹۸۳)؛ استناد مبنا: Bandura (1977) بر یادگیری اجتماعی.', '43a9bf562b10592fe44e9bf42f1da33afaaed8186bcec99d815963196e193dd9', 10, NOW(), NOW());
