-- card-111: امکان‌دهی‌ها
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`) VALUES
('doc-card-111', 'card', 'card-111', 'mc-111', 'امکان‌دهی‌ها', 'Affordances', 'theory', 'ویژگی‌های یک فناوری، کنش‌هایی را که برای کاربر ممکن یا دشوار می‌شوند تعیین می‌کند، اما این امکان‌ها هنگام استفاده و در بافت اجتماعی فعال می‌شوند. امکان‌دهی رابطه‌ای است میان ویژگی‌های ابژه و توانایی‌ها و اهداف کاربر، نه صفت ذاتی فناوری.', 'https://resaname.ir/cards/card-111', 'fa', NULL, NULL, 'a1b7815c570b52bc8cce70ce723537035e9513522983cfde0deed88deb3d8f23', '2026-10-14 01:36:04', NOW());
INSERT INTO `ai_document_sections` (`id`, `document_id`, `section_key`, `section_title`, `content`, `content_hash`, `sort_order`, `created_at`, `updated_at`) VALUES
('sec-card-111-1', 'doc-card-111', 'definition', 'تعریف', 'مطالعات فناوری و ارتباطات / نظریه رسانه دیجیتال

ویژگی‌های یک فناوری، کنش‌هایی را که برای کاربر ممکن یا دشوار می‌شوند تعیین می‌کند، اما این امکان‌ها هنگام استفاده و در بافت اجتماعی فعال می‌شوند. امکان‌دهی رابطه‌ای است میان ویژگی‌های ابژه و توانایی‌ها و اهداف کاربر، نه صفت ذاتی فناوری.', 'dbf6cd202b0084d1fbf75fecd1cff84536c207010f5322c0fbb6ae52b02c5d55', 1, NOW(), NOW()),
('sec-card-111-2', 'doc-card-111', 'theoretical_framework', 'چارچوب نظری', '۱. بنیان و منطق نظری
امکان‌دهی‌ها اینترنت و پلتفرم‌های دیجیتال را محیط رسانه‌ای تازه‌ای می‌داند که منطق ارتباط، تولید و تبادل را دگرگون کرده است. جیمز گیبسون (۱۹۷۹) استدلال کرد که در عصر شبکه، واحد تحلیل دیگر پیام یا کانال نیست، بلکه پلتفرم است: زیرساخت فنی-اقتصادی که کاربران، محتوا و سرمایه را به هم وصل می‌کند. در این چارچوب، خودِ طراحی زیرساخت — پروتکل، کارکرد و الگوریتم — رفتار اجتماعی را شکل می‌دهد، نه صرفاَ محتوای عبوری.

بر اساس امکان‌دهی‌ها، فناوری ابزاری خنثی نیست، بلکه عنصر فعالی‌ساز و دگرسازِ عادات اجتماعی است. جیمز گیبسون (۱۹۷۹) فرایندی را تحلیل کرد که فناوری تازه، از ورود و پذیرش، به زندگی روزمره می‌آمیزد، نقش‌ها و روابط را بازنشانی می‌کند و سرانجام «طبیعی» به نظر می‌رسد. ادعای محوری این است که هر نوسازی فناورانه با یک بازنشانی نظم اجتماعی همراه است و مطالعه‌ی فناوری را نمی‌توان از مطالعه‌ی قدرت، اقتصاد و فرهنگ جدا کرد.

امکان‌دهی‌ها پلتفرم را بوم‌زمینه‌ای چندوجهی می‌داند که در آن اثر شبکه، داده و حکمرانی با هم ساختار رقابت و قدرت را تعیین می‌کنند. جیمز گیبسون (۱۹۷۹) تأکید کرد که پلتفرم هم‌زمان فناوری، بازار و شیوه‌ی حکمرانی است و قدرت آن از کنترل بر «قوانین بازی» — چشم‌اندازی، دسترسی و معامله — می‌آید. این رویکرد، تحلیل پلتفرم را در تقاطع جامعه‌شناسی فناوری، اقتصاد و حکمرانی جای می‌دهد.

۲. ساختارهای مفهومی
• پلتفرم (Platform): زیرساخت دیجیتالی که بازیگران متعدد را گرد هم می‌آورد و تعامل آن‌ها را میانجی می‌کند.
• کارکرد/امکان (Affordance): قابلیت‌های کنشی که طراحی فناوری به کاربر پیشنهاد می‌دهد و عادت‌های او را شکل می‌دهد.
• اثر شبکه‌ای (Network Effect): پدیده‌ای که ارزش یک سرویس دیجیتال با افزایش کاربران آن بزرگ‌تر می‌شود.
• حکمرانی الگوریتمی (Algorithmic Governance): فرایندی که الگوریتم‌ها درباره‌ی چشم‌اندازی، اولویت‌بندی و دسترسی تصمیم می‌گیرند.
• زیرساخت دیجیتال (Digital Infrastructure): لایه‌ی فنی پایینی (سرور، پروتکل، شبکه) که خدمات بر آن ساخته', '18740fd0da28b8a9a139d09bcf7328346062468aafbc41b39e553658bf17726a', 2, NOW(), NOW()),
('sec-card-111-3', 'doc-card-111', 'components', 'اجزای نظری', 'امکان‌دهی ادراک‌شده در برابر واقعی؛ ویژگی‌های فنی؛ هدف کاربر؛ بافت؛ قابلیت دیدن (Visibility)، ویرایش‌پذیری، پاسخ‌پذیری.', 'b7b98024da074f8f09eccad7e3ced9bb8588dd038068ad574e47c05fc9e340c2', 3, NOW(), NOW()),
('sec-card-111-4', 'doc-card-111', 'applications', 'کاربردها', 'می‌شوند.
• پذیرش (Adoption): فرایند ورود فناوری به عادات کاربران و سازمان‌ها و تثبیت آن.
• شکاف دیجیتال (Digital Divide): نابرابری ساختاری در دسترسی به فناوری دیجیتال، استفاده از آن و بهره‌مندی از آن.
• پلتفرمی‌شدن (Platformization): فرایند گسترش منطق و ارزش‌های پلتفرم به حوزه‌های دیگر زندگی اجتماعی.

۳. نمونه‌های تحلیلی
ظهور پلتفرم‌های ویدیویی کوتاه امروز کمتر به کیفیت محتوای تولیدی بازمی‌گردد و بیشتر به طراحی فید الگوریتمی: فید با کارکرد «اسکرول بی‌پایان» و پیشنهاد شخصی‌سازی‌شده، خودِ عادت مصرف چند ساعته را می‌سازد.

حکمرانی پلتفرم‌های بزرگ — نظارت بر محتوا، تعلیق حساب، اولویت‌بندی در جست‌وجو — در عمل نوعی قدرت شبه‌قضایی بر میلیاردها کاربر است که بدون شفافیت و پاسخگویی معیارهای دولتی اعمال می‌شود.

گوشی‌های هوشمند در عرض چند سال عادات ارتباط اجتماعی، خبرخوانی و خرید را تغییر داده‌اند؛ نمونه‌ی کلاسیکی از اینکه چگونه پذیرش یک فناوری عادات روزمره را از خبرنامه‌ی صبحگاهی تا خرید نیمه‌شب بازنشانی می‌کند.

جابه‌جایی بسیاری از خدمات عمومی و تجاری به اپلیکیشن‌ها نمونه‌ای از پلتفرمی‌شدن است: منطق امتیازدهی، حساب کاربری و داده وارد حوزه‌هایی شده که پیش از این بیرون از بازار بودند (بهداشت، آموزش، مشارکت مدنی).

رقابت صنعت استریم بر «محتوای انحصاری» استراتژی است برای بهره‌گیری از اثر شبکه‌ای: تمرکز مخاطب روی یک پلتفرم، ارزش آن را هم برای کاربران و هم برای تولیدکنندگان بزرگ‌تر می‌کند.

شکاف دیجیتال تنها درباره‌ی دسترسی به اینترنت نیست: تفاوت میان جوانی شهری که محتوا تولید می‌کند و مسنی روستایی که مصرف‌کننده‌ی منفعل است، نشان می‌دهد شکاف در سطح مهارت، زبان و قدرت اقتصادی نیز کار می‌کند.

