-- card-121: مدل‌های چهارگانه روابط عمومی
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`) VALUES
('doc-card-121', 'card', 'card-121', 'mc-121', 'مدل‌های چهارگانه روابط عمومی', 'Four Models of Public Relations', 'model', 'گرونیگ و هانت چهار الگوی روابط عمومی را طبقه‌بندی کردند: انتشاراتی (Press Agentry)، اطلاع‌رسانی عمومی (Public Information)، دوطرفه نامتقارن (Two-Way Asymmetrical) و دوطرفه متقارن (Two-Way Symmetrical). الگوهای نخست بیشتر بر انتقال پیام یک‌طرفه تمرکز دارند؛ الگوهای دوطرفه بر تغییر متقابل دیدگاه …', 'https://resaname.ir/cards/card-121', 'fa', NULL, NULL, '9455299959d0ac27547ab45e9b2c472847a469b9b75c89724ffb566212ce248b', '2026-10-14 01:36:01', NOW());
INSERT INTO `ai_document_sections` (`id`, `document_id`, `section_key`, `section_title`, `content`, `content_hash`, `sort_order`, `created_at`, `updated_at`) VALUES
('sec-card-121-1', 'doc-card-121', 'definition', 'تعریف', 'روابط عمومی / ارتباطات سازمانی

گرونیگ و هانت چهار الگوی روابط عمومی را طبقه‌بندی کردند: انتشاراتی (Press Agentry)، اطلاع‌رسانی عمومی (Public Information)، دوطرفه نامتقارن (Two-Way Asymmetrical) و دوطرفه متقارن (Two-Way Symmetrical). الگوهای نخست بیشتر بر انتقال پیام یک‌طرفه تمرکز دارند؛ الگوهای دوطرفه بر تغییر متقابل دیدگاه سازمان و جمهور. الگوی دوطرفه متقارن به‌عنوان الگوی هنجاری مطلوب معرفی شد.', '4c9f979a489f3f1454cc9fec80de77bb210b530e4860a683144c078fb2087d79', 1, NOW(), NOW()),
('sec-card-121-2', 'doc-card-121', 'theoretical_framework', 'چارچوب نظری', '۱. بنیان و منطق نظری
مدل‌های چهارگانه روابط عمومی رسانه را به‌مثابه سازمان‌های استراتژیکی می‌داند که تحت ساختار بازار، الگوی مالکیت و انگیزه‌های اقتصادی شکل می‌گیرند. جیمز گرونیگ (۱۹۸۴) استدلال کرد که برای فهم رسانه باید فراتر از محتوای پیام برویم و شرایط اقتصادی و سازمانی تولید محتوا را تحلیل کنیم: چه کسی کانال‌ها را مالک است، درآمدها از کجا تأمین می‌شوند و رقابت چه محدودیت‌هایی بر سازمان‌ها تحمیل می‌کند. در این چارچوب، تصمیمات محتوایی نتیجه‌ی تلاقی منطق بازار و استراتژی سازمانی است.

بر اساس مدل‌های چهارگانه روابط عمومی، تولید محتوای رسانه‌ای فرایندی بازاری است که در آن سرمایه، نیروی کار و مخاطبان میان سازمان‌های متعدد در رقابت توزیع می‌شوند. این چارچوب که به جیمز گرونیگ نسبت داده می‌شود (۱۹۸۴)، ساختار مالکیت، رقابت و مقیاس در اقتصاد رسانه را تحلیل می‌کند تا نشان دهد چگونه انگیزه‌های سازمانی بر جریان محتوا شکل می‌دهند. پیش از آنکه بپرسیم پیام رسانه چگونه اثر می‌گذارد، باید بپرسیم این پیام‌ها در چه شرایط اقتصادی و در اختیار چه کسانی تولید می‌شوند.

مدل‌های چهارگانه روابط عمومی رسانه را به‌عنوان صنعتی استراتژیک در بازارهای دوسویّه‌ی مخاطب و تبلیغ‌دهنده (و در عصر دیجیتال، پلتفرم) می‌داند. جیمز گرونیگ (۱۹۸۴) تأکید کرد که مدل کسب‌وکار — اشتراک، تبلیغات یا درآمدزایی از داده — ماهیت رابطه‌ی سازمان رسانه‌ای با مخاطب را تعیین می‌کند و در نتیجه ساختار محتوا را شکل می‌دهد. این رویکرد اقتصاد رسانه را در دل اقتصاد سازمان‌های صنعتی و مدیریت استراتژیک جای می‌دهد.

۲. ساختارهای مفهومی
• تمرکز مالکیت رسانه‌ای (Media Ownership Concentration): میزان تجمّع کانال‌های رسانه‌ای در دستان معدودی از مالکان و پیامدهای آن بر تنوع محتوا.
• مدل کسب‌وکار (Business Model): سازوکار مشخصی که سازمان رسانه‌ای از طریق آن درآمد می‌آورد: تبلیغات، اشتراک، سرپرستی یا فروش داده.
• بهای مقیاس (Economies of Scale): کاهش هزینه‌ی واحد تولید با افزایش حجم، که به سود سازمان‌های بزرگ است.
• بازار دوسویه (Two-Sided Market): بازارهایی با دو گروه کاربر مکمّل (مانند مخاطب و تبلیغ‌دهنده) که ارزش هر گروه به دیگری وابسته است.
• اثر شبکه‌ای (Network Effect): پدیده‌ای که در آن ارزش یک پلتفرم برای هر کاربر با افزایش تعداد کاربران دیگر بیشتر می‌شود.
• استراتژی رقابتی (Competitive Strategy):', 'ca9d2a8c7b16d13db35b8f0db6f0d271894a907b211f105eb3456cef9240be43', 2, NOW(), NOW()),
('sec-card-121-3', 'doc-card-121', 'components', 'اجزای نظری', 'جهت ارتباط (یک‌طرفه/دوطرفه)؛ تقارن در تأثیرگذاری؛ اهداف سازمانی؛ نتایج برای جمهور.', '1dfcb8d0c230e548c824fb76f984df98ec2fffe443db488ef7202ced7fd0e34a', 3, NOW(), NOW()),
('sec-card-121-4', 'doc-card-121', 'applications', 'کاربردها', 'انتخاب‌هایی که سازمان برای کسب مزیت پایدار در برابر رقبای بازار انجام می‌دهد.
• سرمایه انسانی (Human Capital): دانش، مهارت و تجربه‌ی نیروی کار به‌عنوان منبع ارزش‌آفرینی در سازمان.
• صنعت خلاق (Creative Industry): صنایعی که محصول اصلی آن‌ها محتوای فرهنگی و خلاق است و با عدم‌قطعیت بالای تقاضا روبه‌روند.

۳. نمونه‌های تحلیلی
در تمرکز روزافزون صنعت پخش، خرید یک استودیوی تولید بزرگ توسط یک پلتفرم استریم نمونه‌ای از استراتژی عمودی در خدمت بهای مقیاس است: هدف، کاهش وابستگی به محتوای بیرونی و هم‌زمان بزرگ‌تر کردن پایگاه مخاطب و داده است.

در مطبوعات، گروه‌های روزنامه‌ای که فعالیت خود را به تلویزیون و فضای دیجیتال گسترش داده و درآمدها را فراتر از تبلیغات متنوع کرده‌اند، نمونه‌ی استراتژی تنوع‌بخشی برای حفظ بقا در بازاری رو به افول هستند.

وقتی یک خبرگزاری بزرگ از مدل درآمدی تبلیغاتی به مدل اشتراک‌دار می‌رود، در عمل تعریف خود از رابطه با مخاطب را بازنویسی می‌کند: مخاطب دیگر کالایی نیست که به تبلیغ‌دهنده فروخته شود، بلکه مشتری است؛ این جابه‌جایی اولویت‌های محتوایی و پاسخگویی رسانه را تغییر می‌دهد.

یک روزنامه‌ی محلی کوچک با اتکا به یارانه‌های جمعی و نشریات خبری پولی، در برابر منطق مقیاس پلتفرم‌ها مقاومت می‌کند؛ استراتژی‌ای که واکنشی است به ناتوانی سازمان‌های کوچک در رقابت مستقیم برای توجه.

رقابت پلتفرم‌های محتوا بر «محتوای انحصاری» نمونه‌ای از منطق بازار دوسویه است: از یک سو تولیدکنندگانی که محتوا و داده ارائه می‌دهند و از سوی دیگر مخاطبانی که توجه خود را عرضه می‌کنند؛ پلتفرم با کاهش هزینه‌ی تعامل میان این دو سمت سود می‌برد.

در صنعت رسانه، ورود شرکت‌های تولیدی از دل شبکه‌های پخش و مذاکره‌ی آن‌ها بر سر سهم درآمدها، نمونه‌ای عملی است از تبدیل سرمایه‌ی انسانی و خلاق به قدرت چانه‌زنی در بازار.

۴. نقدها و چالش‌ها
۱. تقلیل رسانه به منطق بازار: این چارچوب گرایش دارد بُعد فرهنگی و سیاسی محتوا را به‌عنوان اثرات فرعی بازار در نظر بگیرد و کارکرد عمومی و اجتماعی رسانه را دست‌کم بگیرد.
۲. ساختار متغیر در عصر دیجیتال: مدل‌های کلاسیک ساختار بازار و رقابت (تمرکز، مانع ورود) با واقعیت خدمات رایگان، بازارهای دوسویه و پلتفرمی‌شدن هم‌خوانی کامل ندارند.
۳. دشواری سنجش: مفاهیمی مانند «توجه» و «ارزش مخاطب» در عصر پلتفرم معیارهای اندازه‌گیری معتبر و استانداردی ندار', '89e9fb262cd329ee72f405e5388d1f0cdbd6f0a4d300a9d44522cb563cd2117a', 4, NOW(), NOW()),
('sec-card-121-5', 'doc-card-121', 'examples', 'مثال‌ها', 'تحلیل اینکه یک شرکت در بحران تازه، صرفاً بیانیه صادر می‌کند (الگوی اطلاع‌رسانی) یا با ذی‌نفعان گفت‌وگو و تعدیل موضع دارد (الگوی متقارن).', 'dc1455aad6cbdb4f998c7ab156f50772c616ae62321b3e3b6fdfacb68189f866', 5, NOW(), NOW()),
('sec-card-121-6', 'doc-card-121', 'criticism', 'نقدها', 'الگوی متقارن بیشتر هنجاری است و در عمل اغلب با منافع قدرتمند سازمانی ناسازگار است. این الگوها به تفاوت‌های نهادی و فرهنگی کمتر توجه دارند.', 'e8900a2fb1b44b3b644093c0f29787ee37393a3b4e9d25ca35713dff98ab1530', 6, NOW(), NOW()),
('sec-card-121-10', 'doc-card-121', 'references', 'منابع', 'کتاب «اقتصاد رسانه» (ریچارد هاردوود، ۲۰۱۰)؛ کتاب «انقلاب پلتفرمی» (پarker، وان آلستاین و چوداری، ۲۰۱۶)؛ کتاب «صنایع فرهنگی» (دیوید هسمندهال، ۲۰۰۲)؛ استناد مبنا: Rochet & Tirole (2003) بر بازارهای دوسویه.', '2efe013f44cc9e6c640f0ec3c5d85d71a0c3438be40fbf8e3fff258b56a68c32', 10, NOW(), NOW());
