INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`) VALUES
('doc-card-122', 'card', 'card-122', 'mc-122', 'نظریه ارتباطات بحران وضعیتی', 'Situational Crisis Communication Theory', 'theory', 'نوع بحران میزان مسئولیت درک‌شده سازمان و در نتیجه تهدید سمعه را تعیین می‌کند. کومز راهبردهای پاسخ را در چهار دسته قرار داد: انکار (Denial)، کاهش‌دهی (Diminishment)، بازسازی (Rebuilding: جبران و عذرخواهی) و تقویت (Bolstering: یادآوری نکات مثبت پیشین). انتخاب راهبرد باید با میزان مسئولیت درک‌شده …', 'https://resaname.ir/cards/card-122', 'fa', NULL, NULL, '4d72632eae9cd27dcfb960dd0f94fccc117e198db241bb520ae31d4a0f45ca5e', '2026-10-14 01:36:04', NOW());
INSERT INTO `ai_document_sections` (`id`, `document_id`, `section_key`, `section_title`, `content`, `content_hash`, `sort_order`, `created_at`, `updated_at`) VALUES
('sec-card-122-1', 'doc-card-122', 'definition', 'تعریف', 'مدیریت بحران / ارتباطات سازمانی

نوع بحران میزان مسئولیت درک‌شده سازمان و در نتیجه تهدید سمعه را تعیین می‌کند. کومز راهبردهای پاسخ را در چهار دسته قرار داد: انکار (Denial)، کاهش‌دهی (Diminishment)، بازسازی (Rebuilding: جبران و عذرخواهی) و تقویت (Bolstering: یادآوری نکات مثبت پیشین). انتخاب راهبرد باید با میزان مسئولیت درک‌شده هم‌خوان باشد؛ بحران با مسئولیت بالا نیازمند عذرخواهی و جبران است.', '9eab5bff7255910010c0e1615c5ca0db9ced2e7fd0153802e1fc585d1ab3811c', 1, NOW(), NOW()),
('sec-card-122-2', 'doc-card-122', 'theoretical_framework', 'چارچوب نظری', '۱. بنیان و منطق نظری
نظریه ارتباطات بحران وضعیتی رسانه را به‌مثابه سازمان‌های استراتژیکی می‌داند که تحت ساختار بازار، الگوی مالکیت و انگیزه‌های اقتصادی شکل می‌گیرند. تیموتی کومز (۲۰۰۷) استدلال کرد که برای فهم رسانه باید فراتر از محتوای پیام برویم و شرایط اقتصادی و سازمانی تولید محتوا را تحلیل کنیم: چه کسی کانال‌ها را مالک است، درآمدها از کجا تأمین می‌شوند و رقابت چه محدودیت‌هایی بر سازمان‌ها تحمیل می‌کند. در این چارچوب، تصمیمات محتوایی نتیجه‌ی تلاقی منطق بازار و استراتژی سازمانی است.

بر اساس نظریه ارتباطات بحران وضعیتی، تولید محتوای رسانه‌ای فرایندی بازاری است که در آن سرمایه، نیروی کار و مخاطبان میان سازمان‌های متعدد در رقابت توزیع می‌شوند. این چارچوب که به تیموتی کومز نسبت داده می‌شود (۲۰۰۷)، ساختار مالکیت، رقابت و مقیاس در اقتصاد رسانه را تحلیل می‌کند تا نشان دهد چگونه انگیزه‌های سازمانی بر جریان محتوا شکل می‌دهند. پیش از آنکه بپرسیم پیام رسانه چگونه اثر می‌گذارد، باید بپرسیم این پیام‌ها در چه شرایط اقتصادی و در اختیار چه کسانی تولید می‌شوند.

نظریه ارتباطات بحران وضعیتی رسانه را به‌عنوان صنعتی استراتژیک در بازارهای دوسویّه‌ی مخاطب و تبلیغ‌دهنده (و در عصر دیجیتال، پلتفرم) می‌داند. تیموتی کومز (۲۰۰۷) تأکید کرد که مدل کسب‌وکار — اشتراک، تبلیغات یا درآمدزایی از داده — ماهیت رابطه‌ی سازمان رسانه‌ای با مخاطب را تعیین می‌کند و در نتیجه ساختار محتوا را شکل می‌دهد. این رویکرد اقتصاد رسانه را در دل اقتصاد سازمان‌های صنعتی و مدیریت استراتژیک جای می‌دهد.

۲. ساختارهای مفهومی
• تمرکز مالکیت رسانه‌ای (Media Ownership Concentration): میزان تجمّع کانال‌های رسانه‌ای در دستان معدودی از مالکان و پیامدهای آن بر تنوع محتوا.
• مدل کسب‌وکار (Business Model): سازوکار مشخصی که سازمان رسانه‌ای از طریق آن درآمد می‌آورد: تبلیغات، اشتراک، سرپرستی یا فروش داده.
• بهای مقیاس (Economies of Scale): کاهش هزینه‌ی واحد تولید با افزایش حجم، که به سود سازمان‌های بزرگ است.
• بازار دوسویه (Two-Sided Market): بازارهایی با دو گروه کاربر مکمّل (مانند مخاطب و تبلیغ‌دهنده) که ارزش هر گروه به دیگری وابسته است.
• اثر شبکه‌ای (Network Effect): پدیده‌ای که در آن ارزش یک پلتفرم برای هر کاربر با افزایش تعداد کاربران دیگر بیشتر می‌شود.
• استراتژی رقابتی (Competitive Strategy): ا', '25069ac69e0c3dc8e572350c16f38c4f8c03174257b6238675f9f5d15c63de81', 2, NOW(), NOW()),
('sec-card-122-3', 'doc-card-122', 'components', 'اجزای نظری', 'نوع بحران؛ مسئولیت درک‌شده؛ تاریخچه سازمان؛ تهدید سمعه؛ راهبرد پاسخ؛ سرعت پاسخ.', '0d5dd7ef47c05800a893b4cc5e368c4dd71d9bfadf4737d5126e71be729cd8f2', 3, NOW(), NOW()),
('sec-card-122-4', 'doc-card-122', 'applications', 'کاربردها', 'نتخاب‌هایی که سازمان برای کسب مزیت پایدار در برابر رقبای بازار انجام می‌دهد.
• سرمایه انسانی (Human Capital): دانش، مهارت و تجربه‌ی نیروی کار به‌عنوان منبع ارزش‌آفرینی در سازمان.
• صنعت خلاق (Creative Industry): صنایعی که محصول اصلی آن‌ها محتوای فرهنگی و خلاق است و با عدم‌قطعیت بالای تقاضا روبه‌روند.

۳. نمونه‌های تحلیلی
در تمرکز روزافزون صنعت پخش، خرید یک استودیوی تولید بزرگ توسط یک پلتفرم استریم نمونه‌ای از استراتژی عمودی در خدمت بهای مقیاس است: هدف، کاهش وابستگی به محتوای بیرونی و هم‌زمان بزرگ‌تر کردن پایگاه مخاطب و داده است.

در مطبوعات، گروه‌های روزنامه‌ای که فعالیت خود را به تلویزیون و فضای دیجیتال گسترش داده و درآمدها را فراتر از تبلیغات متنوع کرده‌اند، نمونه‌ی استراتژی تنوع‌بخشی برای حفظ بقا در بازاری رو به افول هستند.

وقتی یک خبرگزاری بزرگ از مدل درآمدی تبلیغاتی به مدل اشتراک‌دار می‌رود، در عمل تعریف خود از رابطه با مخاطب را بازنویسی می‌کند: مخاطب دیگر کالایی نیست که به تبلیغ‌دهنده فروخته شود، بلکه مشتری است؛ این جابه‌جایی اولویت‌های محتوایی و پاسخگویی رسانه را تغییر می‌دهد.

یک روزنامه‌ی محلی کوچک با اتکا به یارانه‌های جمعی و نشریات خبری پولی، در برابر منطق مقیاس پلتفرم‌ها مقاومت می‌کند؛ استراتژی‌ای که واکنشی است به ناتوانی سازمان‌های کوچک در رقابت مستقیم برای توجه.

رقابت پلتفرم‌های محتوا بر «محتوای انحصاری» نمونه‌ای از منطق بازار دوسویه است: از یک سو تولیدکنندگانی که محتوا و داده ارائه می‌دهند و از سوی دیگر مخاطبانی که توجه خود را عرضه می‌کنند؛ پلتفرم با کاهش هزینه‌ی تعامل میان این دو سمت سود می‌برد.

در صنعت رسانه، ورود شرکت‌های تولیدی از دل شبکه‌های پخش و مذاکره‌ی آن‌ها بر سر سهم درآمدها، نمونه‌ای عملی است از تبدیل سرمایه‌ی انسانی و خلاق به قدرت چانه‌زنی در بازار.

۴. نقدها و چالش‌ها
۱. تقلیل رسانه به منطق بازار: این چارچوب گرایش دارد بُعد فرهنگی و سیاسی محتوا را به‌عنوان اثرات فرعی بازار در نظر بگیرد و کارکرد عمومی و اجتماعی رسانه را دست‌کم بگیرد.
۲. ساختار متغیر در عصر دیجیتال: مدل‌های کلاسیک ساختار بازار و رقابت (تمرکز، مانع ورود) با واقعیت خدمات رایگان، بازارهای دوسویه و پلتفرمی‌شدن هم‌خوانی کامل ندارند.
۳. دشواری سنجش: مفاهیمی مانند «توجه» و «ارزش مخاطب» در عصر پلتفرم معیارهای اندازه‌گیری معتبر و استانداردی ندارن', '76037a3c3b5991e3e2fe590d1598943efac177890e6e74aead67beb7924f309c', 4, NOW(), NOW()),
('sec-card-122-5', 'doc-card-122', 'examples', 'مثال‌ها', 'تحلیل بیانیه یک شرکت پس از فاش‌شدن نقص محصول، و ارزیابی اینکه آیا راهبرد با سطح مسئولیت درک‌شده هم‌خوان بوده است.', '24460f8c420257831ec8fc952150e98f0ec45414be79337bae2147f6320b41e3', 5, NOW(), NOW()),
('sec-card-122-6', 'doc-card-122', 'criticism', 'نقدها', 'مدل بر کنترل سمعه سازمان متمرکز است و صدای ذی‌نفعان آسیب‌دیده و تصحیح‌گری شبکه‌های اجتماعی را کم‌اهمیت می‌داند.', 'b5323d5aab70f5f9de815f672b5a3851db2818289d34915c0f2aa4de50ee0c4c', 6, NOW(), NOW()),
