-- card-128: ارتباطات مسئولیت اجتماعی شرکتی
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`) VALUES
('doc-card-128', 'card', 'card-128', 'mc-128', 'ارتباطات مسئولیت اجتماعی شرکتی', 'CSR Communication', 'theory', 'کرول مسئولیت شرکت را در چهار لایه‌ی اقتصادی، قانونی، اخلاقی و بشردوستانه سازمان‌دهی کرد. ارتباطات CSR این ادعاها را به ذی‌نفعان منتقل می‌کند. اعتبار این ارتباطات به همخوانی ادعا با عمل و شفافیت گزارش‌دهی بستگی دارد؛ در غیر این صورت، خطر «سبزشویی» (Greenwashing) وجود دارد.', 'https://resaname.ir/cards/card-128', 'fa', NULL, NULL, 'ef8824872c52f671ad33061f51cf3170e98dfff88a602a2854df632b5e861f9a', '2026-10-14 01:00:20', NOW());
INSERT INTO `ai_document_sections` (`id`, `document_id`, `section_key`, `section_title`, `content`, `content_hash`, `sort_order`, `created_at`, `updated_at`) VALUES
('sec-card-128-1', 'doc-card-128', 'definition', 'تعریف', 'ارتباطات سازمانی / مسئولیت اجتماعی

کرول مسئولیت شرکت را در چهار لایه‌ی اقتصادی، قانونی، اخلاقی و بشردوستانه سازمان‌دهی کرد. ارتباطات CSR این ادعاها را به ذی‌نفعان منتقل می‌کند. اعتبار این ارتباطات به همخوانی ادعا با عمل و شفافیت گزارش‌دهی بستگی دارد؛ در غیر این صورت، خطر «سبزشویی» (Greenwashing) وجود دارد.', 'b1d29bf2ee17ae5c5c5e7826f19669bb152239521405f314978e34e88b639a3b', 1, NOW(), NOW()),
('sec-card-128-2', 'doc-card-128', 'theoretical_framework', 'چارچوب نظری', '۱. بنیان و منطق نظری
ارتباطات مسئولیت اجتماعی شرکتی روابط عمومی را فرایند مدیریت ارتباط دوسویه‌ی سازمان با عموم‌هایش می‌داند: شناسایی عموم‌ها، درک انتظارهای آن‌ها، تنظیم پیام و پایش بازخورد. آرچی کرول (۱۹۹۱ (۱۹۹۱) در این چارچوب، روابط عمومی را نه صرفاَ «تبلیغ» بلکه «مدیریت اعتبار» تعریف کرد؛ اعتباری که سرمایه‌ی بلندمدت سازمان است.

بر اساس ارتباطات مسئولیت اجتماعی شرکتی، هدف روابط عمومی، «افزودن اعتبار» به سازمان ازطریق شفافیت، پاسخگویی و اعتمادسازی است. آرچی کرول (۱۹۹۱ (۱۹۹۱) نشان داد که در بحران، سازمانی که اعتبار دارد، «بانک اعتباری»‌ای دارد که می‌تواند به آن تکیه کند؛ این چارچوب در سطح میانی تحلیل، روابط عمومی را به «مدیریت ریسک سازمانی» ارتقا می‌دهد.

ارتباطات مسئولیت اجتماعی شرکتی را می‌توان پاسخی به شکاف میان «ارتباطات یک‌سویه» (تبلیغات، اطلاع‌رسانی) و «گفت‌وگوی واقعی» دانست: در عصر شبکه‌ها، عموم‌ها دیگر فقط شنونده نیستند، بلکه سخنران و پایشگر‌اند. آرچی کرول (۱۹۹۱ (۱۹۹۱) در این چارچوب، دوسویه‌ی بودن، شفافیت و هماهنگی پیام را اصول بنیادین روابط عمومی معاصر قرار داد.

۲. ساختارهای مفهومی
• عموم (Publics): گروه‌هایی که با یک مسئله‌ی مشترک با سازمان درگیرند و بر تصمیمات آن اثر می‌گذارند.
• اعتبار (Credibility): ادراک صداقت، شفافیت و امانتداری سازمان که در طول زمان ساخته می‌شود.
• مدیریت بحران (Crisis Management): مجموعه‌ی اقدامات پیشگیرانه، واکنشی و بازیابی پس از بحران سازمانی.
• گفت‌وگوی دوسویه (Two-Way Dialogue): ارتباطی که در آن سازمان نه فقط پیام می‌فرستد، بلکه گوش می‌دهد و پاسخ می‌دهد.
• شهرت سازمانی (Organizational Reputation): تصویر کلانی که عموم‌ها در ذهن خود از سازمان دارند و بر رفتار آن‌ها اثر می‌گذارد.
• پایش و شنود (Monitoring & Listening): رصد مستمر صحبت‌های عموم‌ها در رسانه‌ها و شبکه‌های اجتماعی.
• پیام‌های هم‌خوان (Consistent Messaging): هماهنگی پیام سازمان در تمام کانال‌ها و تمام موقعیت‌ها.
• پاسخگویی (Accountability): تعهد', 'e06e77e7fc25c2656975623ecc3b50cd731bf0380f78d280fc454372291a7f2f', 2, NOW(), NOW()),
('sec-card-128-3', 'doc-card-128', 'components', 'اجزای نظری', 'لایه‌های مسئولیت؛ انگیزه‌ی ارتباط؛ همخوانی ادعا و عمل؛ شفافیت؛ گزارش‌دهی؛ ذی‌نفعان.', 'e82d19dddecf36c163b552984a08cf41b1137fdb5af3b9587a84cfb62dfbc6f7', 3, NOW(), NOW()),
('sec-card-128-4', 'doc-card-128', 'applications', 'کاربردها', 'سازمان به توضیح علل تصمیمات و پذیرش مسئولیت در برابر عموم‌ها.

۳. نمونه‌های تحلیلی
وقتی یک شرکت پس از رسوایی محیطی، به‌جای انکار، «پذیرش مسئولیت + طرح اصلاح + گزارش‌دهی شفاف» را اعلام می‌کند، در عمل از «بانک اعتباری» استفاده می‌کند: عمومی، بر اساس سوابق شفافیت آن شرکت، به پیامش اعتماد می‌کند.

در بحران یک پرونده‌ی حقوقی، شرکتی که «گفت‌وگوی دوسویه» را اجرا می‌کند (پرسش‌های رسانه و عموم را می‌شنود و پاسخ می‌دهد)، در مقایسه با شرکتی که فقط «بیانیه‌ی رسمی» منتشر می‌کند، اعتماد بیشتری حفظ می‌کند.

پایش شبکه‌های اجتماعی نشان می‌دهد که یک «شکایت کوچک» از یک محصول، اگر بی‌پاسخ بماند، می‌تواند به «بحران شهرت» تبدیل شود؛ در مقابل، پاسخ سریع و صادقانه، «بانک اعتبار» را پر می‌کند.

وقتی یک برند ورزشی از یک چهره‌ی ورزشی «گسل» می‌کند، انتخاب «چه کسی می‌گوید، چه می‌گوید، از چه کانالی» — همان «هماهنگی پیام» — تعیین می‌کند که پیام، «مسئولیت‌پذیری» خوانده شود یا «پنهان‌کاری».

در بحران یک شرکت هواپیمایی، شرکتی که «پایش» را جدی می‌گیرد، می‌داند عمومی «چه نگرانی‌ای» دارد و پاسخش را دقیقاً به همان نگرانی می‌سپارد؛ شرکتی که «پایش» نمی‌کند، به «سوئال» عمومی پاسخ «غلط» می‌دهد و بحران را عمیق‌تر می‌کند.

«پاسخگویی» در عمل به این معناست که سازمان «چرا این تصمیم را گرفت» را توضیح می‌دهد، حتی وقتی توضیح، محبوب نیست؛ این «شفافیت نامطلوب» گاهی ارزشمندتر از «پاسخ محبوب اما مبهم» است.

۴. نقدها و چالش‌ها
۱. مرز میان «روابط عمومی» و «تبلیغات»: در عمل، مرز این دو اغلب کمرنگ است و بسیاری از اقدامات «روابط عمومی»، ماهیت تبلیغاتی دارند؛ این چارچوب باید بتواند «ارزش افزوده» دوگانگی را توضیح دهد.
۲. مسئله‌ی «اعتبار» و سنجش آن: اعتبار یک مفهوم ادراکی است و سنجش دقیق آن (فراتر از نظرسنجی‌های کلی) دشوار است؛ شاخص‌های اعتبار اغلب بازتاب «خوداوری» هستند، نه «واقعیت».
۳. غفلت از «عمومی‌های ضعیف»: چارچوب‌های روابط عمومی عمدتا بر «عمومی‌های قدرتمند» (رسانه‌ها، مقامات) تمرکز دارند و صدای', 'ef2f8f4038b276b0028c2ed35a7c90e01830371f326b796e37f4e04e6f4c3719', 4, NOW(), NOW()),
('sec-card-128-5', 'doc-card-128', 'examples', 'مثال‌ها', 'تحلیل گزارش پایداری یک شرکت انرژی: آیا تعهدات اقلیمی آن با سرمایه‌گذاری‌های واقعی هم‌خوان است؟', 'ac98dae70a48ce1a824bb687a9992fb42da8040f7a2ed5c2564a72172bdeae4c', 5, NOW(), NOW()),
('sec-card-128-6', 'doc-card-128', 'criticism', 'نقدها', 'ارتباطات CSR اغلب توصیفی و خودارزیابانه‌اند. تعریف CSR نیز در ادبیات متنوع است و یکدست نیست.', 'bab9b714af83f74040b96130ba97a2b17b258c77c123da5ccaf2fb48f7d33239', 6, NOW(), NOW()),
('sec-card-128-10', 'doc-card-128', 'references', 'منابع', 'کتاب «روابط عمومی: یک تاریخ» (گرانیگ، ۱۹۸۳)؛ کتاب «مدیریت شهرت» (فولبر و همکاران، ۲۰۰۰)؛ کتاب «بحران و مدیریت بحران» (کوئین، ۱۹۸۴)؛ استناد مبنا: Grunig & Hunt (1984) بر مدل دوسوئی.', 'b05e7a8e8dabfbc480d9bb6194dcce3bf1ba25f623895694e68511e5d1a1075b', 10, NOW(), NOW());
