-- card-166: صنایع فرهنگی
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`) VALUES
('doc-card-166', 'card', 'card-166', 'mc-166', 'صنایع فرهنگی', 'The Cultural Industries', 'theory', 'تولید کالاهای نمادین و فرهنگی به سبب عدم قطعیت سلیقه مخاطب همواره با ریسک مالی بسیار بالایی روبه‌رو است. صنایع فرهنگی از سازوکارهایی نظیر قالب‌بندی ستاره‌ها، ژانرها و ادغام افقی برای مهار این ریسک استفاده می‌کنند و برخلاف ادعاهای آرمان‌گرایانه، دیجیتالی‌شدن نتوانسته هژمونی سرمایه‌داری در تولید …', 'https://resaname.ir/cards/card-166', 'fa', 'بریتانیایی', 'international', 'bf57f5d4153f49491e706d24abfb14dfad1f96cb7cb574895bffdf59bd5a1f79', '2026-10-14 01:36:05', NOW());
INSERT INTO `ai_document_sections` (`id`, `document_id`, `section_key`, `section_title`, `content`, `content_hash`, `sort_order`, `created_at`, `updated_at`) VALUES
('sec-card-166-1', 'doc-card-166', 'definition', 'تعریف', 'اقتصاد سیاسی انتقادی / مطالعات فرهنگی نهادی

تولید کالاهای نمادین و فرهنگی به سبب عدم قطعیت سلیقه مخاطب همواره با ریسک مالی بسیار بالایی روبه‌رو است. صنایع فرهنگی از سازوکارهایی نظیر قالب‌بندی ستاره‌ها، ژانرها و ادغام افقی برای مهار این ریسک استفاده می‌کنند و برخلاف ادعاهای آرمان‌گرایانه، دیجیتالی‌شدن نتوانسته هژمونی سرمایه‌داری در تولید فرهنگ را بشکند.', '89749b7d4a0269f61bcbffc1ccb0aa4929ab017f36ba08a85d8fc3243e1a07aa', 1, NOW(), NOW()),
('sec-card-166-2', 'doc-card-166', 'theoretical_framework', 'چارچوب نظری', '۱. بنیان نظری: از «صنعت فرهنگ» به «صنایع فرهنگی»
مفهوم «صنایع فرهنگی» (Cultural Industries) را دیوید هزموندهالگ (David Hesmondhalgh) در کتاب ۲۰۰۲ خود (ویرایش چهارم ۲۰۱۹) به‌شکل «سنتز انتقادی» «صنعت فرهنگ» (Culture Industry) مکتب فرانکفورت مطرح کرد. آدورنو و هورکهایمر «صنعت فرهنگ» را اصطلاحی «تقدیرکننده» — برای محکومیت ادغام کامل فرهنگ و سرمایه — به‌کار برده بودند، در حالی که هزموندهالگ «صنایع فرهنگی» را مفهومی «تحلیلی» می‌داند: صنایعی که کالاهای «نمادین» (موسیقی، فیلم، نشر، بازی) تولید می‌کنند و ساختار تولید و مصرفشان با «ساختار ریسک» مشخصی همراه است.

۲. منطق محوری: مدیریت ریسک در اقتصاد خلاق
ادعای تحلیلی محوری این نظریه: کالاهای نمادین «پیش‌از‌فروش» نامطمئن‌اند — پیش از تولید، هیچ‌کس نمی‌', 'e2e6a4c575f4567e62c9585e8c9764759decdc6088445fc69619328253c7d054', 2, NOW(), NOW()),
('sec-card-166-3', 'doc-card-166', 'components', 'اجزای نظری', 'کالایی‌شدن فرهنگ، تولید نمادین، مدیریت ریسک خلاقیت، جبران مازاد (Overproduction)، همگرایی دیجیتال و تمرکز انحصاری.', '192fcf5171884e6cb2b91a4bb40c9383ec57168a3fa1a1a2307c8a12f6b6ac73', 3, NOW(), NOW()),
('sec-card-166-4', 'doc-card-166', 'applications', 'کاربردها', 'داند کدام آهنگ پرفروش و کدام فیلم پرفروش خواهد بود. این «عدم‌قطعیت سلیقه‌ی مخاطب»، صنایع فرهنگی را ناگزیر می‌سازد سازوکارهای «مدیریت ریسک» بسازند: (۱) نظام «ستاره» (بازگشت‌پذیری نام اثبات‌شده برای کاهش عدم‌قطعیت)، (۲) «ژانر» و «فرمت» (تکثیر موفقیت)، (۳) «ادغام افقی» (اتصال تولید، توزیع و نمایش)، (۴) «داده» و «پیش‌آزمایش» (گروه‌های کانونی، متریک‌های استریم). هزموندهالگ این ساختار را «منطق صنایع فرهنگی» می‌نامد: پارادوکس «تولید نظام‌مند نوآوری».

۳. دیجیتالی‌شدن و هژمونی: آیا ساختار عوض شده است؟
یکی از مهم‌ترین ادعاهای ویرایش ۲۰۱۹: «دیجیتالی‌شدن» تولید فرهنگی را — برخلاف ادعای نظریه‌های «حذف واسطه‌ها» — «دموکراتیزه» نکرده، بلکه تمرکز را عمیق‌تر کرده است: لایه‌ی «پلتفرم» (اپل، گوگل، آمازون، نت', '7245d91e57b69800178fccc7f90ec03aaa2eb8870d479d2e598bea1a4f548c4f', 4, NOW(), NOW()),
('sec-card-166-5', 'doc-card-166', 'examples', 'مثال‌ها', 'سلطه ابرشرکت‌های هالیوود و غول‌های استریمینگ نظیر نتفلیکس و دیزنی بر توزیع جهانی فیلم و سریال علیرغم تکثیر محتواهای یوتیوب و تیک‌تاک.', '57bcb2e36cf629d803edf5b4233e90dc1351ec77739366196ea71f4cbd6fcf17', 5, NOW(), NOW()),
('sec-card-166-6', 'doc-card-166', 'criticism', 'نقدها', 'تمرکز پژوهش‌های این نظریه عمدتاً بر الگوهای صنایع سرگرمی بریتانیا و آمریکا است و در تعمیم به بازارهای محلی و بومی با محدودیت روبه‌رو است.', '0a4e129a79c662ba20e3bcbb29f41473530e3c26e13cd51b35e82da49714a467', 6, NOW(), NOW()),
('sec-card-166-10', 'doc-card-166', 'references', 'منابع', 'کتاب جریان‌ساز «صنایع فرهنگی» (دیوید هزموندهالگ، ویرایش چهارم ۲۰۱۹).', '71b695f31fc2191f3dc13b2cbc186307ce9bf880bd6114ba2f85d031de4c49f1', 10, NOW(), NOW());
