-- card-201: فرضیه‌ی مالیخولیای سیاسی
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`) VALUES
('doc-card-201', 'card', 'card-201', 'mc-201', 'فرضیه‌ی مالیخولیای سیاسی', 'Media Malaise Hypothesis', 'hypothesis', 'پوشش تلویزیونی سیاست بیشتر بر درگیری، رسوایی و بازی قدرت متمرکز است تا بر مسائل عمومی و عملکرد نهادها. این پوشش بدبینی و بی‌اعتمادی به نهادهای سیاسی را افزایش می‌دهد و مشارکت را کاهش می‌دهد.', 'https://resaname.ir/cards/card-201', 'fa', NULL, NULL, '5175d3cb14767b5934d89e789c7947a379800b367ec01c0ae9bfc8c8e44dfa5a', '2026-10-14 01:36:05', NOW());
INSERT INTO `ai_document_sections` (`id`, `document_id`, `section_key`, `section_title`, `content`, `content_hash`, `sort_order`, `created_at`, `updated_at`) VALUES
('sec-card-201-1', 'doc-card-201', 'definition', 'تعریف', 'مطالعات رأی‌دهی و اعتماد سیاسی / اثرات رسانه‌ای

پوشش تلویزیونی سیاست بیشتر بر درگیری، رسوایی و بازی قدرت متمرکز است تا بر مسائل عمومی و عملکرد نهادها. این پوشش بدبینی و بی‌اعتمادی به نهادهای سیاسی را افزایش می‌دهد و مشارکت را کاهش می‌دهد.', '5a3e03e950efe79a1d44d2b0d4cb861b44d186e0cab5ddd540dfa5c40df4bc6f', 1, NOW(), NOW()),
('sec-card-201-2', 'doc-card-201', 'theoretical_framework', 'چارچوب نظری', '۱. بنیان و منطق نظری
فرضیه‌ی مالیخولیای سیاسی رسانه را «سازوکار حاکمیت» می‌داند: نه صرفاَ «ابزار» دولت، بلکه «زمینه‌ی» قدرت، رقابت و مشروعیت‌سازی. مایکل رابینسون (۱۹۷۶) نشان داد که «قدرت» بر رسانه از سه مسیر عمل می‌کند: «مالکیت» (چه کسی مالک است)، «محتوا» (چه چیزی گفته می‌شود) و «فرمت» (چگونه گفته می‌شود). این چارچوب در سطح کلان تحلیل، رسانه را از «ابزار» به «نهاد سیاسی» ارتقا می‌دهد.

بر اساس فرضیه‌ی مالیخولیای سیاسی، «حاکمیت رسانه» یعنی «مدیریت جریان معنا» در سطح کلان: «سیاست‌گذاری رسانه‌ای»، «قانون» و «نظم‌های» خودتنظیمی، «قواعد بازی» را تعیین می‌کنند. مایکل رابینسون (۱۹۷۶) در این چارچوب، «نظم رسانه‌ای» را نه «پایان» بلکه «نقطه‌ی آغاز» تحلیل قرار داد: نظم، میدان نبرد سیاسی است.

فرضیه‌ی مالیخولیای سیاسی را می‌توان پاسخی به شکاف میان «نظریه‌ی وابستگی» (رسانه، بازتاب قدرت) و «نظریه‌ی استقلال» (رسانه، حواله‌گر قدرت) دانست: قدرت، نه «بازتاب» بلکه «بازتولید» است. مایکل رابینسون (۱۹۷۶) در این چارچوب، «قدرت رسانه» را «دوسویه» خواند: رسانه هم «تحت تأثیر» قدرت است و هم «تولیدکننده» آن.

۲. ساختارهای مفهومی
• قدرت بر رسانه (Power over Media): «مالکیت»، «فروشگاه» و «نظم» که «محتوا» را از پیش تعیین می‌کنند؛ پرسش «چه کسی تصمیم می‌گیرد؟» در کانون است.
• قدرت رسانه (Power of Media): توانایی رسانه در «تدوین» واقعیت، «مشروعیت‌سازی» و «نهادسازی»؛ رسانه، «قدرت نرم» تولید می‌کند.
• نظم رسانه‌ای (Media Regulation): «قواعد بازی» رسانه: «قانون»، «نظم‌های» خودتنظیمی و «نظم‌های» دولتی؛ هر «نظم»، انتخاب سیاسی است.
• سیاست‌گذاری رسانه‌ای (Media Policy): فرایند «تصمیم‌گیری» درباره‌ی «ساختار»، «مالکیت» و «محتوای» رسانه؛ «نهادها» و «گروه‌های» فشار در کانون‌اند.
• مالکیت رسانه‌ای (Media Ownership): «ساختار» مالک', 'f253bf03a32e9cb3648431dd3e3a8499651f30ae56a37f529f909a707260049d', 2, NOW(), NOW()),
('sec-card-201-3', 'doc-card-201', 'components', 'اجزای نظری', 'نوع پوشش (درگیری در برابر محتوای سیاستی)؛ اعتماد سیاسی؛ بدبینی؛ مصرف تلویزیون؛ مشارکت.', '769c80ed43951484b7d41facc5ac2c2a8f075938eee75db811d19a78644c4b6d', 3, NOW(), NOW()),
('sec-card-201-4', 'doc-card-201', 'applications', 'کاربردها', 'یت (تمرکز/تعدد) که «محتوا» را از پیش شکل می‌دهد؛ «مالکیت» و «اقتصاد» در هم تنیده‌اند.
• مشروعیت‌سازی (Legitimation): رسانه با «گزارش» و «بازنمایی»، «حاکمیت» را «مشروع» می‌نمایاند؛ «تصویر» و «زبان»، ابزار «مشروعیت‌سازی»‌اند.
• حاکمیت رسانه‌ای (Media Governance): «مدیریت کلان» رسانه: «نهادها»، «قوانین»، «نظم‌ها» و «نهادسازی» که «جریان معنا» را «تنظیم» می‌کنند.
• رقابت رسانه‌ای (Media Competition): «رقابت» بین نهادهای رسانه‌ای برای «دسته‌ی» هدف، «سرمایه» و «اعتبار»؛ «رقابت» و «تمرکز» در «موازنه»‌اند.

۳. نمونه‌های تحلیلی
وقتی «رسانه‌ای» از «انتخابات» گزارش می‌دهد، «موضوعات» و «زبان» آن، «مشروعیت‌سازی» است: «نحوه‌ی» گزارش، «حاکمیت» را «طبیعی» می‌نمایاند.

«مالکیت رسانه‌ای» در عمل: وقتی یک «گروه اقتصادی» «رسانه» می‌خرد، «محتوا» از «پیش» شکل می‌گیرد؛ «مالکیت» و «اقتصاد» در هم تنیده‌اند.

«نظم رسانه‌ای» در «ایران» به «قانون» و «نظم دولتی» تقلیل نمی‌یابد: «نظم‌های» خودتنظیمی (کمیته‌های رسانه‌ای) و «نظم‌های» فرهنگی (سلیقه‌ی حاکم) هم در کانون‌اند.

«سیاست‌گذاری رسانه‌ای» در «اتحادیه اروپا» با «قانون خدمات رسانه‌ای» و «حریم خصوصی» تعریف می‌شود و «رقابت» بین «پلتفرم‌ها» و «رسانه‌های» سنتی، «موضوع» اصلی است.

«قدرت رسانه» در «بحران» به «تدوین» واقعیت تبدیل می‌شود: «نحوه‌ی» گزارش «بحران»، «واکنش» عمومی را «تعیین» می‌کند.

«حاکمیت رسانه‌ای» در «عصر دیجیتال» با «پلتفرم‌ها» «بازتعریف» می‌شود: «الگوریتم» و «داده»، «نظم» تازه‌ای از «حاکمیت» تولید می‌کنند که «قانون» سنتی، «توصیف» نمی‌کند.

۴. نقدها و چالش‌ها
۱. «قدرت بر رسانه» و «قدرت رسانه» مرز «کمرنگ» دارند: «تدوین» و «تلقین» در هم تنیده‌اند و «سنجش» مستقل آن‌ها دشوار است.
۲. «نظم رسانه‌ای» به «قانون» تقلیل می‌یابد: «نظم‌های» خودتنظیمی، «فرهنگی» و «اقتص', '588f15106a900595b8259688c8405f3afccf4ed3c50c841db106208be56882a6', 4, NOW(), NOW()),
('sec-card-201-5', 'doc-card-201', 'examples', 'مثال‌ها', 'بررسی اینکه آیا پوشش پرتکرار رسوایی‌های مالی نمایندگان در شبکه‌های خبری با کاهش اعتماد به پارلمان همراه است.', '8607bd8385da86d3048f3388fff0f1979aa66877539e9b3535050c943bf46a2b', 5, NOW(), NOW()),
('sec-card-201-6', 'doc-card-201', 'criticism', 'نقدها', 'پژوهش‌های بعدی نشان داده‌اند که رابطه‌ی علیّت میان مصرف رسانه و بی‌اعتمادی دو‌سویه است و بسیاری از نتایج به دوره‌ی خاص و داده‌های آمریکایی وابسته‌اند.', '41f82ea7e15f6a9001454c240d242752f7a1b9d93562453989dadf417ac2f687', 6, NOW(), NOW()),
('sec-card-201-10', 'doc-card-201', 'references', 'منابع', 'کتاب «قدرت و رسانه» (مورگن و همکاران، ۱۹۹۸)؛ کتاب «نظم رسانه‌ای» (نیکلسون و همکاران، ۲۰۰۴)؛ کتاب «سیاست‌گذاری رسانه‌ای» (بن و همکاران، ۲۰۰۲)؛ کتاب «اقتصادسیاست رسانه» (گورینگ و پاول، ۱۹۹۴).', '3936fe241b543d42170763c866dd088d055f4ed4434b7cf1089f51425607d1ae', 10, NOW(), NOW());
