-- card-231: میانجی‌گری فرهنگی
INSERT INTO `ai_documents` (`id`, `source_type`, `source_id`, `slug`, `title`, `english_title`, `content_type`, `summary`, `canonical_url`, `language`, `country`, `origin`, `content_hash`, `source_updated_at`, `indexed_at`) VALUES
('doc-card-231', 'card', 'card-231', 'mc-231', 'میانجی‌گری فرهنگی', 'Mediations', 'theory', 'معنای رسانه‌ای در جریان یک‌طرفه‌ی تولید به مصرف شکل نمی‌گیرد، بلکه از میانجی‌هایی مانند فرهنگ محلی، خانواده، طبقه، زمان و تجربه‌ی زیسته عبور می‌کند. مارتین‌باربرو تمرکز تحلیل را از «خود رسانه» به «فرایندهای میانجی‌گری» منتقل می‌کند.', 'https://resaname.ir/cards/card-231', 'fa', NULL, NULL, 'a548a665db17a91e444b746f441816f5d6a52a545344b1f0655f102e7ff72188', '2026-10-14 01:36:05', NOW());
INSERT INTO `ai_document_sections` (`id`, `document_id`, `section_key`, `section_title`, `content`, `content_hash`, `sort_order`, `created_at`, `updated_at`) VALUES
('sec-card-231-1', 'doc-card-231', 'definition', 'تعریف', 'مطالعات فرهنگی آمریکای لاتین / مطالعات مخاطب

معنای رسانه‌ای در جریان یک‌طرفه‌ی تولید به مصرف شکل نمی‌گیرد، بلکه از میانجی‌هایی مانند فرهنگ محلی، خانواده، طبقه، زمان و تجربه‌ی زیسته عبور می‌کند. مارتین‌باربرو تمرکز تحلیل را از «خود رسانه» به «فرایندهای میانجی‌گری» منتقل می‌کند.', 'b4dbd3145420c8a9d46970032daeab2dc7f836e4b44221fe13171fb3ac8a8ae5', 1, NOW(), NOW()),
('sec-card-231-2', 'doc-card-231', 'theoretical_framework', 'چارچوب نظری', '۱. بنیان و منطق نظری
میانجی‌گری فرهنگی «روش» را «بافت» «معنا» می‌داند: نه «ابزار» «تحلیل» بلکه «بافت» «تحلیل». خسوس مارتین‌باربرو (۱۹۸۷) در این چارچوب، «روش» را «بافت» «معرفت» تعریف کرد: «روش»، «بافت» «تحلیل» است و «تحلیل»، «بافت» «روش».

بر اساس میانجی‌گری فرهنگی، «روش» «دیالکتیک» «نظریه» و «داده» است: «نظریه»، «بافت» «تحلیل» است و «داده»، «بافت» «نظریه». خسوس مارتین‌باربرو (۱۹۸۷) در این چارچوب، «روش» را «بافت» «اعتماد» تعریف کرد: «اعتماد» در «روش» «ساخته» می‌شود، نه در «نتیجه».

میانجی‌گری فرهنگی را می‌توان پاسخی به شکاف میان «روش» «کمّی» (تعمیم) و «روش» «کیفی» (عمق) دانست: «روش»، «بافت» «معرفت» است و «معرفت»، «بافت» «روش». خسوس مارتین‌باربرو (۱۹۸۷) در این چارچوب، «روش» را «بافت» «بازی» تعریف کرد: «تحلیل»، «بازی» با «داده» است.

۲. ساختارهای مفهومی
• روش کمّی (Quantitative Method): «اندازه‌گیری» و «تعمیم»: «داده» «عددی» و «تحلیل» «آمار».
• روش کیفی (Qualitative Method): «فهم» و «عمق»: «داده» «کیفی» و «تحلیل» «تفسیر».
• روش ترکیبی (Mixed Methods): «ترکیب» «کمّی» و «کیفی»: «بافت» «بزرگ» و «بافت» «کوچک» در هم تنیده‌اند.
• پیمایش (Survey): «اندازه‌گیری» «دسته‌ی» «بزرگ»: «سؤال» و «پاسخ» در «بافت» «دسته».
• تحلیل محتوا (Content Analysis): «تحلیل» «متن»: «کد» و «فراوانی» در «بافت» «متن».
• نظریه داده بنیادین (Grounded Theory): «نظریه» از «داده»: «بافت» «داده»، «نظریه» «ساخته» می‌شود.
